import org.apache.commons.cli2.Option;
import org.apache.commons.cli2.commandline.WriteableCommandLineImpl;
import org.apache.commons.cli2.option.DefaultOption;
import org.junit.Before;
import org.junit.Test;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Set;
import java.util.HashSet;

import static org.junit.Assert.*;

public class WriteableCommandLineImplGetValuesTest {

    private WriteableCommandLineImpl commandLine;
    private Option mockOption;
    private Option anotherMockOption;

    @Before
    public void setUp() {
        mockOption = new DefaultOption("test", "test", 0, 1, null, null, 't', null, 0);
        anotherMockOption = new DefaultOption("another", "another", 0, 1, null, null, 'a', null, 0);
        commandLine = new WriteableCommandLineImpl(mockOption, new ArrayList<>());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testGetValues_NullOption() {
        commandLine.getValues(null, Collections.emptyList());
    }

    @Test
    public void testGetValues_NoValuesSet_NoFallback_NoInternalDefault() {
        List<String> result = commandLine.getValues(mockOption, null);
        assertNotNull(result);
        assertTrue(result.isEmpty());
        // R3: The returned list is always a new mutable list, ensuring that modifications
        // by the caller do not affect the internal state of the command line, and vice-versa.
        // If no values are found after all attempts, an immutable empty list is returned.
        // The returned list should be empty and immutable in this case.
        try {
            result.add("should not be added");
            fail("Should have returned an immutable empty list");
        } catch (UnsupportedOperationException e) {
            // Expected
        }
    }

    @Test
    public void testGetValues_NoValuesSet_EmptyFallback_NoInternalDefault() {
        List<String> fallback = Collections.emptyList();
        List<String> result = commandLine.getValues(mockOption, fallback);
        assertNotNull(result);
        assertTrue(result.isEmpty());
        // R3: The returned list is always a new mutable list, ensuring that modifications
        // by the caller do not affect the internal state of the command line, and vice-versa.
        // If no values are found after all attempts, an immutable empty list is returned.
        // The returned list should be empty and immutable in this case.
        try {
            result.add("should not be added");
            fail("Should have returned an immutable empty list");
        } catch (UnsupportedOperationException e) {
            // Expected
        }
    }

    @Test
    public void testGetValues_NoValuesSet_WithFallback_NoInternalDefault() {
        List<String> fallback = Arrays.asList("fallback1", "fallback2");
        List<String> result = commandLine.getValues(mockOption, fallback);
        assertNotNull(result);
        assertFalse(result.isEmpty());
        assertEquals(fallback.size(), result.size());
        assertTrue(result.containsAll(fallback));
        // R3: The returned list is always a new mutable list
        // Modifications to the returned list should not affect the fallback list
        result.add("new value");
        assertFalse(fallback.contains("new value"));
        assertEquals(fallback.size() + 1, result.size());
    }

    @Test
    public void testGetValues_NoValuesSet_NoFallback_WithInternalDefault() {
        List<String> internalDefaults = Arrays.asList("internal1", "internal2");
        commandLine.setDefaultValues(mockOption, internalDefaults);

        List<String> result = commandLine.getValues(mockOption, null);
        assertNotNull(result);
        assertFalse(result.isEmpty());
        assertEquals(internalDefaults.size(), result.size());
        assertTrue(result.containsAll(internalDefaults));
        // R3: The returned list is always a new mutable list
        // Modifications to the returned list should not affect the internal default list
        result.add("new value");
        assertFalse(internalDefaults.contains("new value"));
        assertEquals(internalDefaults.size() + 1, result.size());
    }

    @Test
    public void testGetValues_NoValuesSet_EmptyFallback_WithInternalDefault() {
        List<String> internalDefaults = Arrays.asList("internal1", "internal2");
        commandLine.setDefaultValues(mockOption, internalDefaults);
        List<String> fallback = Collections.emptyList();

        List<String> result = commandLine.getValues(mockOption, fallback);
        assertNotNull(result);
        assertFalse(result.isEmpty());
        assertEquals(internalDefaults.size(), result.size());
        assertTrue(result.containsAll(internalDefaults));
        // R3: The returned list is always a new mutable list
        result.add("new value");
        assertFalse(internalDefaults.contains("new value"));
        assertEquals(internalDefaults.size() + 1, result.size());
    }

    @Test
    public void testGetValues_NoValuesSet_WithFallback_WithInternalDefault() {
        // Fallback should be prioritized over internal defaults if internal defaults are not explicitly set
        // The docstring says: "If no such values are found, it attempts to use the provided `fallbackDefaultValues` list.
        // If both are absent or empty, it then consults the internal default values configured for the option."
        // This implies fallback takes precedence over internal defaults if fallback is not empty.
        List<String> internalDefaults = Arrays.asList("internal1", "internal2");
        commandLine.setDefaultValues(mockOption, internalDefaults);
        List<String> fallback = Arrays.asList("fallback1", "fallback2");

        List<String> result = commandLine.getValues(mockOption, fallback);
        assertNotNull(result);
        assertFalse(result.isEmpty());
        assertEquals(fallback.size(), result.size());
        assertTrue(result.containsAll(fallback));
        // R3: The returned list is always a new mutable list
        result.add("new value");
        assertFalse(fallback.contains("new value"));
        assertFalse(internalDefaults.contains("new value"));
        assertEquals(fallback.size() + 1, result.size());
    }

    @Test
    public void testGetValues_ValuesExplicitlySet() {
        commandLine.addValue(mockOption, "value1");
        commandLine.addValue(mockOption, "value2");

        List<String> fallback = Arrays.asList("fallback1", "fallback2");
        List<String> internalDefaults = Arrays.asList("internal1", "internal2");
        commandLine.setDefaultValues(mockOption, internalDefaults);

        List<String> result = commandLine.getValues(mockOption, fallback);
        assertNotNull(result);
        assertFalse(result.isEmpty());
        assertEquals(2, result.size());
        assertTrue(result.contains("value1"));
        assertTrue(result.contains("value2"));
        // R3: The returned list is always a new mutable list
        // Modifications to the returned list should not affect the internal state
        result.add("new value");
        assertEquals(3, result.size());
        // R4: Calling getValues again should return a new list, not affected by previous modifications
        List<String> secondResult = commandLine.getValues(mockOption, fallback);
        assertEquals(2, secondResult.size());
        assertFalse(secondResult.contains("new value"));
    }

    @Test
    public void testGetValues_ValuesExplicitlySet_EmptyFallback_EmptyInternalDefault() {
