        List<String> result = commandLine.getValues(mockOption, Collections.emptyList());
        assertNotNull(result);
        assertFalse(result.isEmpty());
        assertEquals(2, result.size());
        assertTrue(result.contains("valueA"));
        assertTrue(result.contains("valueB"));
        // R3: The returned list is always a new mutable list
        result.add("another value");
        assertEquals(3, result.size());
    }

    @Test
    public void testGetValues_MultipleOptions() {
        commandLine.addValue(mockOption, "value1");
        commandLine.addValue(anotherMockOption, "anotherValue1");

        List<String> result1 = commandLine.getValues(mockOption, null);
        List<String> result2 = commandLine.getValues(anotherMockOption, null);

        assertNotNull(result1);
        assertFalse(result1.isEmpty());
        assertEquals(1, result1.size());
        assertTrue(result1.contains("value1"));

        assertNotNull(result2);
        assertFalse(result2.isEmpty());
        assertEquals(1, result2.size());
        assertTrue(result2.contains("anotherValue1"));

        // R4: Modifying one option's values should not affect another's
        result1.add("value2");
        assertEquals(2, result1.size());
        assertEquals(1, commandLine.getValues(anotherMockOption, null).size());
    }

    @Test
    public void testGetValues_ReturnedListIsMutable() {
        commandLine.addValue(mockOption, "initial");
        List<String> result = commandLine.getValues(mockOption, null);
        assertNotNull(result);
        assertFalse(result.isEmpty());
        assertEquals(1, result.size());

        result.add("addedValue");
        assertEquals(2, result.size());
        assertTrue(result.contains("addedValue"));

        // R4: Ensure the original commandLine's internal state is not affected by external modifications
        List<String> originalValues = commandLine.getValues(mockOption, null);
        assertEquals(1, originalValues.size());
        assertFalse(originalValues.contains("addedValue"));
    }

    @Test
    public void testGetValues_FallbackListIsImmutableAfterReturn() {
        List<String> fallback = new ArrayList<>(Arrays.asList("f1"));
        List<String> result = commandLine.getValues(mockOption, fallback);
        assertNotNull(result);
        assertEquals(1, result.size());
        assertTrue(result.contains("f1"));

        // R4: Modifying the original fallback list should not affect the returned list
        fallback.add("f2");
        assertEquals(1, result.size()); // result should still have only "f1"
        assertFalse(result.contains("f2"));
    }

    @Test
    public void testGetValues_InternalDefaultListIsImmutableAfterReturn() {
        List<String> internalDefaults = new ArrayList<>(Arrays.asList("id1"));
        commandLine.setDefaultValues(mockOption, internalDefaults);
        List<String> result = commandLine.getValues(mockOption, null);
        assertNotNull(result);
        assertEquals(1, result.size());
        assertTrue(result.contains("id1"));

        // R4: Modifying the original internal default list should not affect the returned list
        internalDefaults.add("id2");
        assertEquals(1, result.size()); // result should still have only "id1"
