    }

    @Test
    public void testGetValues_EmptyInternalDefault_WithFallback() {
        commandLine.setDefaultValues(mockOption, Collections.emptyList());
        List<String> fallback = Arrays.asList("fb1");
        List<String> result = commandLine.getValues(mockOption, fallback);

