        formatter.findWrapPos("test", 10, -1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testFindWrapPos_StartPosOutOfBounds_TooLarge() {
        formatter.findWrapPos("test", 10, 5);
    }

    @Test
    public void testFindWrapPos_NoWrapNeeded() {
        String text = "short text";
        int width = 20;
        int startPos = 0;
        assertEquals(-1, formatter.findWrapPos(text, width, startPos));

        text = "another short text";
        width = 18;
        startPos = 0;
        assertEquals(-1, formatter.findWrapPos(text, width, startPos));
    }

    @Test
    public void testFindWrapPos_ExplicitNewline() {
        String text = "line1\nline2";
        int width = 10;
        int startPos = 0;
        assertEquals(6, formatter.findWrapPos(text, width, startPos)); // After '\n'

        text = "line1\nline2";
        width = 3;
        startPos = 0;
        assertEquals(6, formatter.findWrapPos(text, width, startPos)); // Newline within width

        text = "line1\nline2";
        width = 1;
        startPos = 0;
        assertEquals(6, formatter.findWrapPos(text, width, startPos)); // Newline within width
    }

    @Test
    public void testFindWrapPos_ExplicitTab() {
        String text = "line1\tline2";
        int width = 10;
        int startPos = 0;
        assertEquals(6, formatter.findWrapPos(text, width, startPos)); // After '\t'

        text = "line1\tline2";
        width = 3;
        startPos = 0;
        assertEquals(6, formatter.findWrapPos(text, width, startPos)); // Tab within width
    }

    @Test
    public void testFindWrapPos_WordBreak_Simple() {
        String text = "word1 word2 word3";
        int width = 7; // "word1 w"
        int startPos = 0;
        assertEquals(6, formatter.findWrapPos(text, width, startPos)); // After "word1 "

        text = "word1 word2 word3";
        width = 13; // "word1 word2 w"
        startPos = 0;
        assertEquals(12, formatter.findWrapPos(text, width, startPos)); // After "word1 word2 "
    }

    @Test
    public void testFindWrapPos_WordBreak_NoSpaceBeforeWidth() {
        String text = "longwordandanother";
        int width = 5;
        int startPos = 0;
        assertEquals(5, formatter.findWrapPos(text, width, startPos)); // Chop at width

        text = "longwordandanother";
        width = 10;
        startPos = 0;
        assertEquals(10, formatter.findWrapPos(text, width, startPos)); // Chop at width
    }

    @Test
    public void testFindWrapPos_WordBreak_ChopAndFindNextSpace() {
        String text = "thisisalongword and then some more";
        int width = 10; // "thisisalon"
        int startPos = 0;
        assertEquals(14, formatter.findWrapPos(text, width, startPos)); // Chops "thisisalongword" at 10, then finds space at 14

        text = "anotherverylongword that needs wrapping";
        width = 8; // "anotherv"
        startPos = 0;
