        startPos = 11;
        assertEquals(22, formatter.findWrapPos(text, width, startPos)); // "second line "

        startPos = 22;
        assertEquals(-1, formatter.findWrapPos(text, width, startPos)); // "third line" fits
    }

    @Test
    public void testFindWrapPos_MixedContent() {
        String text = "word1\nword2 longword word3\tword4";
        int width = 10;
        int startPos = 0;
        assertEquals(6, formatter.findWrapPos(text, width, startPos)); // Newline

