public class StringUtilsNewStringIso8859_1Test {

    @Test
    public void testNewStringIso8859_1_NullInput() {
        assertNull(StringUtils.newStringIso8859_1(null));
    }

    @Test
    public void testNewStringIso8859_1_EmptyByteArray() {
        byte[] emptyBytes = new byte[0];
        assertEquals("", StringUtils.newStringIso8859_1(emptyBytes));
    }

    @Test
    public void testNewStringIso8859_1_BasicLatinCharacters() {
        String original = "Hello World";
        byte[] bytes = original.getBytes(StandardCharsets.ISO_8859_1);
        assertEquals(original, StringUtils.newStringIso8859_1(bytes));
    }

    @Test
    public void testNewStringIso8859_1_ExtendedLatinCharacters() {
        String original = "Grüße aus München"; // Contains characters outside ASCII
        byte[] bytes = original.getBytes(StandardCharsets.ISO_8859_1);
        assertEquals(original, StringUtils.newStringIso8859_1(bytes));
    }

    @Test
    public void testNewStringIso8859_1_AllPossibleBytes() {
        byte[] allBytes = new byte[256];
        for (int i = 0; i < 256; i++) {
            allBytes[i] = (byte) i;
        }
        String expected = new String(allBytes, StandardCharsets.ISO_8859_1);
        assertEquals(expected, StringUtils.newStringIso8859_1(allBytes));
    }

    @Test
    public void testNewStringIso8859_1_RoundTripWithGetBytesIso8859_1() {
        String original = "Test String with some special chars: éàçüö";
        byte[] bytes = StringUtils.getBytesIso8859_1(original);
        assertEquals(original, StringUtils.newStringIso8859_1(bytes));
    }

    @Test
    public void testNewStringIso8859_1_AgreementWithJDKStringConstructor() {
        String original = "Another test string with € symbol (will be replaced by '?')";
        // ISO-8859-1 does not support the Euro symbol, it will be replaced by '?' or similar.
        // We are testing the behavior of ISO-8859-1, not UTF-8.
        byte[] bytes = original.getBytes(StandardCharsets.ISO_8859_1);
        String expected = new String(bytes, StandardCharsets.ISO_8859_1);
        assertEquals(expected, StringUtils.newStringIso8859_1(bytes));
    }

    @Test
    public void testNewStringIso8859_1_LengthInvariant() {
        String original = "Short";
        byte[] bytes = original.getBytes(StandardCharsets.ISO_8859_1);
        assertEquals(original.length(), StringUtils.newStringIso8859_1(bytes).length());

        original = "A much longer string with various characters and numbers 1234567890";
        bytes = original.getBytes(StandardCharsets.ISO_8859_1);
        assertEquals(original.length(), StringUtils.newStringIso8859_1(bytes).length());
    }
