import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.NoSuchElementException;

public class CSVParserIteratorTest {

    @Test
    public void testIteratorEmptyCSV() throws IOException {
        String csvData = "";
        try (Reader reader = new StringReader(csvData);
             CSVParser parser = new CSVParser(reader, CSVFormat.DEFAULT)) {
            Iterator<CSVRecord> iterator = parser.iterator();
            assertFalse("Iterator should not have next for empty CSV", iterator.hasNext());
        }
    }

    @Test
    public void testIteratorSingleRecord() throws IOException {
        String csvData = "header1,header2\nvalue1,value2";
        try (Reader reader = new StringReader(csvData);
             CSVParser parser = new CSVParser(reader, CSVFormat.DEFAULT.withFirstRecordAsHeader())) {
            Iterator<CSVRecord> iterator = parser.iterator();
            assertTrue("Iterator should have next for single record", iterator.hasNext());
            CSVRecord record = iterator.next();
            assertEquals("value1", record.get("header1"));
            assertEquals("value2", record.get("header2"));
            assertFalse("Iterator should not have next after consuming single record", iterator.hasNext());
        }
    }

    @Test
    public void testIteratorMultipleRecords() throws IOException {
        String csvData = "h1,h2\nv1a,v1b\nv2a,v2b\nv3a,v3b";
        try (Reader reader = new StringReader(csvData);
             CSVParser parser = new CSVParser(reader, CSVFormat.DEFAULT.withFirstRecordAsHeader())) {
            Iterator<CSVRecord> iterator = parser.iterator();

            assertTrue(iterator.hasNext());
            CSVRecord record1 = iterator.next();
            assertEquals("v1a", record1.get("h1"));
            assertEquals("v1b", record1.get("h2"));

            assertTrue(iterator.hasNext());
            CSVRecord record2 = iterator.next();
            assertEquals("v2a", record2.get("h1"));
            assertEquals("v2b", record2.get("h2"));

            assertTrue(iterator.hasNext());
            CSVRecord record3 = iterator.next();
            assertEquals("v3a", record3.get("h1"));
            assertEquals("v3b", record3.get("h2"));

            assertFalse("Iterator should not have next after consuming all records", iterator.hasNext());
        }
    }

    @Test(expected = NoSuchElementException.class)
    public void testIteratorNextOnEmpty() throws IOException {
        String csvData = "";
        try (Reader reader = new StringReader(csvData);
             CSVParser parser = new CSVParser(reader, CSVFormat.DEFAULT)) {
            Iterator<CSVRecord> iterator = parser.iterator();
            iterator.next(); // Should throw NoSuchElementException
        }
    }

    @Test(expected = NoSuchElementException.class)
    public void testIteratorNextPastEnd() throws IOException {
        String csvData = "value1";
        try (Reader reader = new StringReader(csvData);
