            Iterator<CSVRecord> iterator = parser.iterator();
            iterator.next();
            iterator.remove(); // Should throw UnsupportedOperationException
        }
    }

    @Test
    public void testIteratorWithHeaderAndNoRecords() throws IOException {
        String csvData = "header1,header2";
        try (Reader reader = new StringReader(csvData);
             CSVParser parser = new CSVParser(reader, CSVFormat.DEFAULT.withFirstRecordAsHeader())) {
            Iterator<CSVRecord> iterator = parser.iterator();
            assertFalse("Iterator should not have next if only header is present", iterator.hasNext());
            assertNotNull("Header map should be initialized", parser.getHeaderMap());
            assertEquals(2, parser.getHeaderMap().size());
        }
    }

    @Test
    public void testIteratorConsistencyWithGetRecords() throws IOException {
        String csvData = "a,b\nc,d\ne,f";
        try (Reader reader = new StringReader(csvData);
             CSVParser parser = new CSVParser(reader, CSVFormat.DEFAULT)) {
            List<CSVRecord> recordsFromIterator = new ArrayList<>();
            for (CSVRecord record : parser) {
                recordsFromIterator.add(record);
