import com.google.gson.stream.JsonWriter;
import org.junit.Before;
import org.junit.Test;

import java.io.IOException;
import java.io.StringWriter;

import static org.junit.Assert.*;

public class JsonWriterValueDoubleTest {

    private StringWriter stringWriter;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() {
        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
    }

    @Test
    public void testValueFiniteDouble() throws IOException {
        double value = 123.45;
        jsonWriter.value(value);
        assertEquals(String.valueOf(value), stringWriter.toString());
    }

    @Test
    public void testValueZeroDouble() throws IOException {
        double value = 0.0;
        jsonWriter.value(value);
        assertEquals(String.valueOf(value), stringWriter.toString());
    }

    @Test
    public void testValueNegativeDouble() throws IOException {
        double value = -987.65;
        jsonWriter.value(value);
        assertEquals(String.valueOf(value), stringWriter.toString());
    }

    @Test
    public void testValueLargeDouble() throws IOException {
        double value = 1.2345678901234567E20;
        jsonWriter.value(value);
        assertEquals(String.valueOf(value), stringWriter.toString());
    }

    @Test
    public void testValueSmallDouble() throws IOException {
        double value = 1.2345678901234567E-20;
        jsonWriter.value(value);
        assertEquals(String.valueOf(value), stringWriter.toString());
    }

    @Test
    public void testValueDoubleInArray() throws IOException {
        double value1 = 1.1;
        double value2 = 2.2;
        jsonWriter.beginArray().value(value1).value(value2).endArray();
        assertEquals("[" + String.valueOf(value1) + "," + String.valueOf(value2) + "]", stringWriter.toString());
    }

    @Test
    public void testValueDoubleInObject() throws IOException {
        double value = 3.14;
        jsonWriter.beginObject().name("pi").value(value).endObject();
        assertEquals("{\"pi\":" + String.valueOf(value) + "}", stringWriter.toString());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValueNaNThrowsIllegalArgumentException() throws IOException {
        jsonWriter.value(Double.NaN);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValuePositiveInfinityThrowsIllegalArgumentException() throws IOException {
        jsonWriter.value(Double.POSITIVE_INFINITY);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testValueNegativeInfinityThrowsIllegalArgumentException() throws IOException {
        jsonWriter.value(Double.NEGATIVE_INFINITY);
    }

    @Test
    public void testValueDoubleChaining() throws IOException {
        double value1 = 10.0;
        double value2 = 20.0;
        JsonWriter chainedWriter = jsonWriter.beginArray().value(value1);
        assertEquals("[" + String.valueOf(value1), stringWriter.toString());
        chainedWriter.value(value2).endArray();
        assertEquals("[" + String.valueOf(value1) + "," + String.valueOf(value2) + "]", stringWriter.toString());
    }

    @Test
    public void testValueDoubleWithDeferredName() throws IOException {
        double value = 123.45;
        jsonWriter.beginObject().name("key").value(value).endObject();
        assertEquals("{\"key\":" + String.valueOf(value) + "}", stringWriter.toString());
    }

    @Test
    public void testValueDoubleWithLenientModeNaN() throws IOException {
        jsonWriter.setLenient(true);
        double value = Double.NaN;
        jsonWriter.value(value);
        assertEquals("NaN", stringWriter.toString());
    }

    @Test
    public void testValueDoubleWithLenientModePositiveInfinity() throws IOException {
        jsonWriter.setLenient(true);
        double value = Double.POSITIVE_INFINITY;
        jsonWriter.value(value);
        assertEquals("Infinity", stringWriter.toString());
    }

    @Test
    public void testValueDoubleWithLenientModeNegativeInfinity() throws IOException {
        jsonWriter.setLenient(true);
        double value = Double.NEGATIVE_INFINITY;
        jsonWriter.value(value);
        assertEquals("-Infinity", stringWriter.toString());
    }

    @Test
    public void testValueDoubleComparisonWithNumberOverload() throws IOException {
        double doubleValue = 123.45;
        jsonWriter.value(doubleValue);
        String doubleOutput = stringWriter.toString();

        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
        Number numberValue = doubleValue;
        jsonWriter.value(numberValue);
        String numberOutput = stringWriter.toString();

        assertEquals(doubleOutput, numberOutput); // R2 agreement between overloads
    }

    @Test
    public void testValueDoubleComparisonWithLongOverload() throws IOException {
        long longValue = 123L;
        double doubleValue = (double) longValue;
        jsonWriter.value(doubleValue);
        String doubleOutput = stringWriter.toString();

        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
        jsonWriter.value(longValue);
        String longOutput = stringWriter.toString();

        assertEquals(doubleOutput, longOutput); // R2 agreement between overloads
    }
}
