import com.google.gson.stream.JsonWriter;
import org.junit.Before;
import org.junit.Test;

import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;

import static org.junit.Assert.*;

public class JsonWriterValueStringTest {

    private StringWriter stringWriter;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() {
        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
    }

    @Test
    public void testValue_stringValue() throws IOException {
        String testString = "hello world";
        jsonWriter.value(testString);
        assertEquals("\"hello world\"", stringWriter.toString());
    }

    @Test
    public void testValue_emptyString() throws IOException {
        String testString = "";
        jsonWriter.value(testString);
        assertEquals("\"\"", stringWriter.toString());
    }

    @Test
    public void testValue_stringWithSpecialChars() throws IOException {
        String testString = "string with \"quotes\" and \\backslashes\\ \n new line \r carriage return \t tab";
        jsonWriter.value(testString);
        assertEquals("\"string with \\\"quotes\\\" and \\\\backslashes\\\\ \\n new line \\r carriage return \\t tab\"", stringWriter.toString());
    }

    @Test
    public void testValue_nullValue() throws IOException {
        jsonWriter.value(null);
        assertEquals("null", stringWriter.toString());
    }

    @Test
    public void testValue_chainedCalls() throws IOException {
        jsonWriter.beginArray()
                .value("first")
                .value("second")
                .endArray();
        assertEquals("[\"first\",\"second\"]", stringWriter.toString());
    }

    @Test
    public void testValue_inObjectField() throws IOException {
        jsonWriter.beginObject()
                .name("key1")
                .value("value1")
                .name("key2")
                .value("value2")
                .endObject();
        assertEquals("{\"key1\":\"value1\",\"key2\":\"value2\"}", stringWriter.toString());
    }

    @Test
    public void testValue_withHtmlSafeEnabled() throws IOException {
        jsonWriter.setHtmlSafe(true);
        String testString = "<script>alert('xss')</script>";
        jsonWriter.value(testString);
        assertEquals("\"\\u003cscript\\u003ealert('xss')\\u003c/script\\u003e\"", stringWriter.toString());
    }

    @Test
    public void testValue_withHtmlSafeDisabled() throws IOException {
        jsonWriter.setHtmlSafe(false);
        String testString = "<script>alert('xss')</script>";
        jsonWriter.value(testString);
        assertEquals("\"<script>alert('xss')</script>\"", stringWriter.toString());
    }

    @Test
    public void testValue_withIndent() throws IOException {
        jsonWriter.setIndent("  ");
        jsonWriter.beginArray()
                .value("item1")
                .value("item2")
                .endArray();
        assertEquals("[\n  \"item1\",\n  \"item2\"\n]", stringWriter.toString());
    }

    @Test
    public void testValue_nullValueWithSerializeNullsFalse() throws IOException {
        jsonWriter.setSerializeNulls(false);
        jsonWriter.beginObject()
                .name("key1")
                .value("value1")
                .name("key2")
                .value(null)
                .endObject();
        assertEquals("{\"key1\":\"value1\"}", stringWriter.toString());
    }

    @Test
    public void testValue_nullValueWithSerializeNullsTrue() throws IOException {
        jsonWriter.setSerializeNulls(true);
        jsonWriter.beginObject()
                .name("key1")
                .value("value1")
                .name("key2")
                .value(null)
                .endObject();
        assertEquals("{\"key1\":\"value1\",\"key2\":null}", stringWriter.toString());
    }

    @Test
    public void testValue_afterOtherValueTypes() throws IOException {
        jsonWriter.beginArray()
                .value(123)
                .value(true)
                .value("string")
                .endArray();
        assertEquals("[123,true,\"string\"]", stringWriter.toString());
    }

    @Test
    public void testValue_overloadAgreementWithBoolean() throws IOException {
        StringWriter swBoolean = new StringWriter();
        JsonWriter jwBoolean = new JsonWriter(swBoolean);
        jwBoolean.value(true);

        StringWriter swString = new StringWriter();
        JsonWriter jwString = new JsonWriter(swString);
        jwString.value("true");

        assertNotEquals(swBoolean.toString(), swString.toString()); // "true" vs "\"true\""
    }

    @Test
    public void testValue_overloadAgreementWithLong() throws IOException {
        StringWriter swLong = new StringWriter();
        JsonWriter jwLong = new JsonWriter(swLong);
        jwLong.value(123L);

        StringWriter swString = new StringWriter();
        JsonWriter jwString = new JsonWriter(swString);
        jwString.value("123");

        assertNotEquals(swLong.toString(), swString.toString()); // "123" vs "\"123\""
    }

    @Test
    public void testValue_overloadAgreementWithDouble() throws IOException {
        StringWriter swDouble = new StringWriter();
        JsonWriter jwDouble = new JsonWriter(swDouble);
        jwDouble.value(123.45);

        StringWriter swString = new StringWriter();
        JsonWriter jwString = new JsonWriter(swString);
        jwString.value("123.45");

        assertNotEquals(swDouble.toString(), swString.toString()); // "123.45" vs "\"123.45\""
    }

    @Test
    public void testValue_withUnicodeCharacters() throws IOException {
        String unicodeString = "你好世界"; // Hello World in Chinese
        jsonWriter.value(unicodeString);
        assertEquals("\"你好世界\"", stringWriter.toString());
    }

    @Test
    public void testValue_withUnicodeEscapeCharactersHtmlSafe() throws IOException {
        jsonWriter.setHtmlSafe(true);
        String unicodeString = "\u2028 \u2029"; // Line Separator, Paragraph Separator
        jsonWriter.value(unicodeString);
        assertEquals("\"\\u2028 \\u2029\"", stringWriter.toString());
    }

    @Test
    public void testValue_withUnicodeEscapeCharactersNotHtmlSafe() throws IOException {
        jsonWriter.setHtmlSafe(false);
        String unicodeString = "\u2028 \u2029"; // Line Separator, Paragraph Separator
        jsonWriter.value(unicodeString);
        assertEquals("\"\\u2028 \\u2029\"", stringWriter.toString());
    }
}
