    public void testValueBooleanFalse() throws IOException {
        jsonWriter.value(false);
        assertEquals("false", stringWriter.toString());
    }

    @Test
    public void testValueBooleanInArray() throws IOException {
        jsonWriter.beginArray();
        jsonWriter.value(true);
        jsonWriter.value(false);
        jsonWriter.endArray();
        assertEquals("[true,false]", stringWriter.toString());
    }

    @Test
    public void testValueBooleanInObject() throws IOException {
        jsonWriter.beginObject();
        jsonWriter.name("key1").value(true);
        jsonWriter.name("key2").value(false);
        jsonWriter.endObject();
        assertEquals("{\"key1\":true,\"key2\":false}", stringWriter.toString());
    }

