    public void testValueBooleanChaining() throws IOException {
        JsonWriter returnedWriter = jsonWriter.value(true);
        assertNotNull(returnedWriter);
        assertTrue(returnedWriter == jsonWriter); // R3: returns this JsonWriter instance
    }

