    public void testValueBooleanWithIndent() throws IOException {
        jsonWriter.setIndent("  ");
        jsonWriter.beginArray();
        jsonWriter.value(true);
        jsonWriter.value(false);
        jsonWriter.endArray();
        assertEquals("[\n  true,\n  false\n]", stringWriter.toString());
    }

