    public void testValueBooleanWithHtmlSafe() throws IOException {
        jsonWriter.setHtmlSafe(true);
        jsonWriter.value(true);
        assertEquals("true", stringWriter.toString()); // Booleans don't contain HTML-unsafe characters
    }

    @Test
    public void testValueBooleanWithLenient() throws IOException {
        jsonWriter.setLenient(true);
        jsonWriter.value(true);
        assertEquals("true", stringWriter.toString()); // Lenient mode doesn't affect boolean writing directly
