import com.google.gson.stream.JsonWriter;
import org.junit.Before;
import org.junit.Test;

import java.io.IOException;
import java.io.StringWriter;

import static org.junit.Assert.*;

public class JsonWriterNullValueTest {

    private StringWriter stringWriter;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() {
        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
    }

    @Test
    public void testNullValueInRoot() throws IOException {
        jsonWriter.nullValue();
        assertEquals("null", stringWriter.toString());
    }

    @Test
    public void testNullValueInArray() throws IOException {
        jsonWriter.beginArray().nullValue().endArray();
        assertEquals("[null]", stringWriter.toString());
    }

    @Test
    public void testNullValueInArrayMultiple() throws IOException {
        jsonWriter.beginArray().value("hello").nullValue().value(123).nullValue().endArray();
        assertEquals("[\"hello\",null,123,null]", stringWriter.toString());
    }

    @Test
    public void testNullValueInObject() throws IOException {
        jsonWriter.beginObject().name("key").nullValue().endObject();
        assertEquals("{\"key\":null}", stringWriter.toString());
    }

    @Test
    public void testNullValueInObjectMultiple() throws IOException {
        jsonWriter.beginObject()
                .name("key1").value("value1")
                .name("key2").nullValue()
                .name("key3").value(true)
                .name("key4").nullValue()
                .endObject();
        assertEquals("{\"key1\":\"value1\",\"key2\":null,\"key3\":true,\"key4\":null}", stringWriter.toString());
    }

    @Test
    public void testNullValueWithSerializeNullsFalse() throws IOException {
        jsonWriter.setSerializeNulls(false);
        jsonWriter.beginObject().name("key").nullValue().endObject();
        assertEquals("{}", stringWriter.toString());
    }

    @Test
    public void testNullValueWithSerializeNullsFalseAndOtherValues() throws IOException {
        jsonWriter.setSerializeNulls(false);
        jsonWriter.beginObject()
                .name("key1").value("value1")
                .name("key2").nullValue()
                .name("key3").value(true)
                .name("key4").nullValue()
                .endObject();
        assertEquals("{\"key1\":\"value1\",\"key3\":true}", stringWriter.toString());
    }

    @Test
    public void testNullValueWithSerializeNullsFalseInArray() throws IOException {
        // serializeNulls only affects named values (object members), not array elements.
        jsonWriter.setSerializeNulls(false);
        jsonWriter.beginArray().value("hello").nullValue().value(123).nullValue().endArray();
        assertEquals("[\"hello\",null,123,null]", stringWriter.toString());
    }

    @Test
    public void testNullValueChaining() throws IOException {
        JsonWriter chainedWriter = jsonWriter.beginObject().name("test").nullValue().endObject();
        assertSame(jsonWriter, chainedWriter);
        assertEquals("{\"test\":null}", stringWriter.toString());
    }

    @Test
    public void testNullValueAfterNameWithoutValue() throws IOException {
        jsonWriter.beginObject().name("field");
        jsonWriter.nullValue();
        jsonWriter.endObject();
        assertEquals("{\"field\":null}", stringWriter.toString());
    }

    @Test
    public void testNullValueAfterNameWithoutValueAndSerializeNullsFalse() throws IOException {
        jsonWriter.setSerializeNulls(false);
        jsonWriter.beginObject().name("field");
        jsonWriter.nullValue();
        jsonWriter.endObject();
        assertEquals("{}", stringWriter.toString());
    }

    @Test
    public void testNullValueWithIndent() throws IOException {
        jsonWriter.setIndent("  ");
        jsonWriter.beginObject().name("key").nullValue().endObject();
        assertEquals("{\n  \"key\": null\n}", stringWriter.toString());
    }

    @Test
    public void testNullValueWithIndentAndSerializeNullsFalse() throws IOException {
        jsonWriter.setIndent("  ");
        jsonWriter.setSerializeNulls(false);
        jsonWriter.beginObject().name("key").nullValue().endObject();
        assertEquals("{}", stringWriter.toString());
    }

    @Test
    public void testNullValueAsFirstElementInArray() throws IOException {
        jsonWriter.beginArray().nullValue().value("test").endArray();
        assertEquals("[null,\"test\"]", stringWriter.toString());
    }

    @Test
    public void testNullValueAsFirstFieldInObject() throws IOException {
        jsonWriter.beginObject().name("first").nullValue().name("second").value("value").endObject();
        assertEquals("{\"first\":null,\"second\":\"value\"}", stringWriter.toString());
