    @Test
    public void testNullValueAsFirstFieldInObjectWithSerializeNullsFalse() throws IOException {
        jsonWriter.setSerializeNulls(false);
        jsonWriter.beginObject().name("first").nullValue().name("second").value("value").endObject();
        assertEquals("{\"second\":\"value\"}", stringWriter.toString());
    }
}
