import com.google.gson.stream.JsonWriter;
import org.junit.Before;
import org.junit.Test;

import java.io.IOException;
import java.io.StringWriter;

import static org.junit.Assert.*;

public class JsonWriterValueDoubleTest {

    private StringWriter stringWriter;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() {
        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
    }

    @Test
    public void testValueFiniteDouble() throws IOException {
        double value = 123.45;
        jsonWriter.value(value);
        assertEquals(String.valueOf(value), stringWriter.toString());

        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
        value = -0.0;
        jsonWriter.value(value);
        assertEquals(String.valueOf(value), stringWriter.toString());

        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
        value = 0.0;
        jsonWriter.value(value);
        assertEquals(String.valueOf(value), stringWriter.toString());

        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
        value = Double.MAX_VALUE;
        jsonWriter.value(value);
        assertEquals(String.valueOf(value), stringWriter.toString());

        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
        value = Double.MIN_VALUE;
        jsonWriter.value(value);
        assertEquals(String.valueOf(value), stringWriter.toString());
    }

    @Test
    public void testValueFiniteDoubleInArray() throws IOException {
        jsonWriter.beginArray();
        double value1 = 1.1;
        jsonWriter.value(value1);
        double value2 = 2.2;
        jsonWriter.value(value2);
        jsonWriter.endArray();
        assertEquals("[" + String.valueOf(value1) + "," + String.valueOf(value2) + "]", stringWriter.toString());
    }

    @Test
    public void testValueFiniteDoubleInObject() throws IOException {
        jsonWriter.beginObject();
        String name = "key";
        double value = 3.14;
        jsonWriter.name(name).value(value);
        jsonWriter.endObject();
        assertEquals("{\"" + name + "\":" + String.valueOf(value) + "}", stringWriter.toString());
    }

    @Test
    public void testValueNaN() throws IOException {
        try {
            jsonWriter.value(Double.NaN);
            fail("Expected IllegalArgumentException for NaN value");
        } catch (IllegalArgumentException e) {
            assertEquals("Numeric values must be finite, but was NaN", e.getMessage());
        }
    }

    @Test
    public void testValuePositiveInfinity() throws IOException {
        try {
            jsonWriter.value(Double.POSITIVE_INFINITY);
            fail("Expected IllegalArgumentException for positive infinity value");
        } catch (IllegalArgumentException e) {
            assertEquals("Numeric values must be finite, but was Infinity", e.getMessage());
        }
    }

    @Test
    public void testValueNegativeInfinity() throws IOException {
        try {
            jsonWriter.value(Double.NEGATIVE_INFINITY);
            fail("Expected IllegalArgumentException for negative infinity value");
        } catch (IllegalArgumentException e) {
            assertEquals("Numeric values must be finite, but was -Infinity", e.getMessage());
        }
    }

    @Test
    public void testValueFiniteDoubleWithIndent() throws IOException {
        jsonWriter.setIndent("  ");
        jsonWriter.beginArray();
        double value = 123.45;
        jsonWriter.value(value);
        jsonWriter.endArray();
        assertEquals("[\n  " + String.valueOf(value) + "\n]", stringWriter.toString());
    }

    @Test
    public void testValueFiniteDoubleWithDeferredName() throws IOException {
        jsonWriter.beginObject();
        jsonWriter.name("doubleField");
        double value = 123.45;
        jsonWriter.value(value);
        jsonWriter.endObject();
        assertEquals("{\"doubleField\":" + String.valueOf(value) + "}", stringWriter.toString());
    }

    @Test
    public void testValueDoubleAgreementWithNumberValue() throws IOException {
        double doubleValue = 123.45;
        jsonWriter.value(doubleValue);
        String outputDouble = stringWriter.toString();

        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
        Number numberValue = doubleValue;
        jsonWriter.value(numberValue);
        String outputNumber = stringWriter.toString();

        assertEquals(outputDouble, outputNumber);
    }

    @Test
    public void testValueDoubleAgreementWithNumberValueNegative() throws IOException {
        double doubleValue = -123.45;
        jsonWriter.value(doubleValue);
        String outputDouble = stringWriter.toString();

        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
        Number numberValue = doubleValue;
        jsonWriter.value(numberValue);
        String outputNumber = stringWriter.toString();

        assertEquals(outputDouble, outputNumber);
    }

    @Test
    public void testValueDoubleAgreementWithNumberValueZero() throws IOException {
        double doubleValue = 0.0;
        jsonWriter.value(doubleValue);
        String outputDouble = stringWriter.toString();

        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
        Number numberValue = doubleValue;
        jsonWriter.value(numberValue);
        String outputNumber = stringWriter.toString();

        assertEquals(outputDouble, outputNumber);
    }
}
