import com.google.gson.stream.JsonWriter;
import org.junit.Before;
import org.junit.Test;

import java.io.IOException;
import java.io.StringWriter;

import static org.junit.Assert.*;

public class JsonWriterValueLongTest {

    private StringWriter stringWriter;
    private JsonWriter jsonWriter;

    @Before
    public void setUp() {
        stringWriter = new StringWriter();
        jsonWriter = new JsonWriter(stringWriter);
    }

    @Test
    public void testValueLongInArray() throws IOException {
        long value = 123456789012345L;
        jsonWriter.beginArray().value(value).endArray();
        assertEquals("[" + value + "]", stringWriter.toString());
    }

    @Test
    public void testValueLongInObject() throws IOException {
        long value = -9876543210L;
        jsonWriter.beginObject().name("longField").value(value).endObject();
        assertEquals("{\"longField\":" + value + "}", stringWriter.toString());
    }

    @Test
    public void testValueLongMultipleTimes() throws IOException {
        long value1 = 1L;
        long value2 = 0L;
        long value3 = -1L;
        jsonWriter.beginArray().value(value1).value(value2).value(value3).endArray();
        assertEquals("[" + value1 + "," + value2 + "," + value3 + "]", stringWriter.toString());
    }

    @Test
    public void testValueLongMaxMinValue() throws IOException {
        jsonWriter.beginArray()
                .value(Long.MAX_VALUE)
                .value(Long.MIN_VALUE)
                .endArray();
        assertEquals("[" + Long.MAX_VALUE + "," + Long.MIN_VALUE + "]", stringWriter.toString());
    }

    @Test
    public void testValueLongZero() throws IOException {
        long value = 0L;
        jsonWriter.value(value);
        assertEquals(String.valueOf(value), stringWriter.toString());
    }

    @Test
    public void testValueLongPositive() throws IOException {
        long value = 123L;
        jsonWriter.value(value);
        assertEquals(String.valueOf(value), stringWriter.toString());
    }

    @Test
    public void testValueLongNegative() throws IOException {
        long value = -456L;
        jsonWriter.value(value);
        assertEquals(String.valueOf(value), stringWriter.toString());
    }

    @Test
    public void testValueLongChaining() throws IOException {
        long value = 789L;
        JsonWriter returnedWriter = jsonWriter.value(value);
        assertSame(jsonWriter, returnedWriter);
        assertEquals(String.valueOf(value), stringWriter.toString());
    }

    @Test
    public void testValueLongAfterName() throws IOException {
        long value = 1000L;
        jsonWriter.beginObject().name("test").value(value).endObject();
        assertEquals("{\"test\":" + value + "}", stringWriter.toString());
    }

    @Test
    public void testValueLongRootValue() throws IOException {
        long value = 500L;
        jsonWriter.value(value);
        assertEquals(String.valueOf(value), stringWriter.toString());
    }

    @Test
    public void testValueLongWithIndent() throws IOException {
        jsonWriter.setIndent("  ");
        long value = 12345L;
        jsonWriter.beginArray().value(value).endArray();
        assertEquals("[\n  " + value + "\n]", stringWriter.toString());
    }

    @Test
    public void testValueLongWithHtmlSafe() throws IOException {
        jsonWriter.setHtmlSafe(true);
        long value = 123L;
        jsonWriter.value(value);
        assertEquals(String.valueOf(value), stringWriter.toString());
    }

    @Test
    public void testValueLongLenient() throws IOException {
        jsonWriter.setLenient(true);
        long value = 123L;
        jsonWriter.value(value);
        assertEquals(String.valueOf(value), stringWriter.toString());
    }

    @Test
    public void testValueLongSerializeNulls() throws IOException {
        jsonWriter.setSerializeNulls(false);
        long value = 123L;
        jsonWriter.value(value);
        assertEquals(String.valueOf(value), stringWriter.toString());
    }

    @Test
    public void testValueLongFollowedByOtherValueTypes() throws IOException {
        long longValue = 123L;
        String stringValue = "test";
        boolean booleanValue = true;
        double doubleValue = 1.23;

        jsonWriter.beginArray()
                .value(longValue)
                .value(stringValue)
                .value(booleanValue)
                .value(doubleValue)
                .endArray();

        assertEquals("[" + longValue + ",\"" + stringValue + "\"," + booleanValue + "," + doubleValue + "]", stringWriter.toString());
    }

    @Test
    public void testValueLongOverloadAgreement() throws IOException {
        long longValue = 42L;
        jsonWriter.value(longValue);
        String outputLong = stringWriter.toString();
        stringWriter = new StringWriter(); // Reset writer
        jsonWriter = new JsonWriter(stringWriter);
        jsonWriter.value((Number) longValue); // Use Number overload
        String outputNumber = stringWriter.toString();
        assertEquals(outputLong, outputNumber);
    }
}
