import java.util.Set;

public class RandomStringUtilsTest {

    private static final int TEST_COUNT = 100; // Number of iterations for random tests

    // R3: Invariant - generated string length should match the count
    @Test
    public void testRandomLength() {
        Random random = new Random();
        for (int i = 0; i < TEST_COUNT; i++) {
            int count = random.nextInt(100) + 1; // count > 0
            String result = org.apache.commons.lang3.RandomStringUtils.random(count, 0, 0, false, false, null, random);
            assertEquals(count, result.length());
        }
    }

    // R3: Invariant - generated string length should be 0 for count 0
    @Test
    public void testRandomLengthZero() {
        Random random = new Random();
        String result = org.apache.commons.lang3.RandomStringUtils.random(0, 0, 0, false, false, null, random);
        assertEquals(0, result.length());
    }

    // R3: Invariant - IllegalArgumentException for negative count
    @Test(expected = IllegalArgumentException.class)
    public void testRandomNegativeCount() {
        org.apache.commons.lang3.RandomStringUtils.random(-1, 0, 0, false, false, null, new Random());
    }

    // R3: Invariant - IllegalArgumentException for null random
    @Test(expected = IllegalArgumentException.class)
    public void testRandomNullRandom() {
