        Random random = new Random();
        for (int i = 0; i < TEST_COUNT; i++) {
            int count = random.nextInt(50) + 1;
            boolean letters = random.nextBoolean();
            boolean numbers = random.nextBoolean();

            String resultFocal = org.apache.commons.lang3.RandomStringUtils.random(count, 0, 0, letters, numbers, null, random);
            String resultOverload = org.apache.commons.lang3.RandomStringUtils.random(count, letters, numbers);

            // We can't assert equality of the strings themselves due to randomness,
            // but we can assert their properties (length and character types).
            assertEquals(count, resultFocal.length());
            assertEquals(count, resultOverload.length());

            if (letters && !numbers) {
                for (char c : resultFocal.toCharArray()) {
                    assertTrue(Character.isLetter(c));
                }
                for (char c : resultOverload.toCharArray()) {
                    assertTrue(Character.isLetter(c));
                }
            } else if (!letters && numbers) {
                for (char c : resultFocal.toCharArray()) {
                    assertTrue(Character.isDigit(c));
                }
