                    assertTrue(Character.isLetterOrDigit(c));
                }
            } else { // neither letters nor numbers, default to ASCII printable
                for (char c : resultFocal.toCharArray()) {
                    assertTrue(c >= 32 && c <= 122); // ASCII printable range
