import org.apache.commons.lang3.StringUtils;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtilsEqualsTest {

    @Test
    public void testEquals_NullInputs() {
        // R3 documented invariants: Two null references are considered to be equal.
        assertTrue(StringUtils.equals(null, null)); // from Javadoc

        // R3 documented invariants: null and non-null are not equal.
        assertFalse(StringUtils.equals(null, "abc")); // from Javadoc
        assertFalse(StringUtils.equals("abc", null)); // from Javadoc
    }

    @Test
    public void testEquals_IdenticalReferences() {
        CharSequence cs = "hello";
        assertTrue(StringUtils.equals(cs, cs));
    }

    @Test
    public void testEquals_EqualContent() {
        // R3 documented invariants: "abc" and "abc" are equal.
        assertTrue(StringUtils.equals("abc", "abc")); // from Javadoc
        assertTrue(StringUtils.equals(new StringBuilder("test"), new StringBuilder("test")));
        assertTrue(StringUtils.equals("hello world", "hello world"));
        assertTrue(StringUtils.equals("", ""));
    }

    @Test
    public void testEquals_DifferentContent() {
        // R3 documented invariants: "abc" and "ABC" are not equal (case-sensitive).
        assertFalse(StringUtils.equals("abc", "ABC")); // from Javadoc
        assertFalse(StringUtils.equals("hello", "world"));
        assertFalse(StringUtils.equals("test", "test "));
        assertFalse(StringUtils.equals(" test", "test"));
    }

    @Test
    public void testEquals_DifferentLength() {
        assertFalse(StringUtils.equals("short", "longer"));
        assertFalse(StringUtils.equals("longer", "short"));
        assertFalse(StringUtils.equals("a", ""));
        assertFalse(StringUtils.equals("", "a"));
    }

    @Test
    public void testEquals_MixedCharSequenceTypes() {
        assertTrue(StringUtils.equals("hello", new StringBuilder("hello")));
        assertTrue(StringUtils.equals(new StringBuilder("world"), "world"));
        assertFalse(StringUtils.equals("hello", new StringBuilder("Hello")));
        assertFalse(StringUtils.equals(new StringBuilder("world"), "World"));
    }

    @Test
    public void testEquals_EmptyAndNull() {
        assertFalse(StringUtils.equals("", null));
        assertFalse(StringUtils.equals(null, ""));
    }

    @Test
    public void testEquals_WithIgnoreCase() {
        // R2 overloads / variants: equalsIgnoreCase should be true where equals is true,
        // and also true for case differences where equals is false.
        CharSequence cs1 = "test";
        CharSequence cs2 = "test";
        assertTrue(StringUtils.equals(cs1, cs2));
        assertTrue(StringUtils.equalsIgnoreCase(cs1, cs2));

        CharSequence cs3 = "Test";
        assertFalse(StringUtils.equals(cs1, cs3));
        assertTrue(StringUtils.equalsIgnoreCase(cs1, cs3));

        // Null handling should be consistent
        assertTrue(StringUtils.equalsIgnoreCase(null, null));
        assertFalse(StringUtils.equalsIgnoreCase(null, "abc"));
        assertFalse(StringUtils.equalsIgnoreCase("abc", null));
    }

    @Test
    public void testEquals_LongStrings() {
        String longString1 = "Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.";
        String longString2 = "Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.";
        String longString3 = "Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliquA."; // Different last char

        assertTrue(StringUtils.equals(longString1, longString2));
        assertFalse(StringUtils.equals(longString1, longString3));
    }
}
