import org.apache.commons.lang3.math.NumberUtils;
import org.junit.Test;
import static org.junit.Assert.*;
import java.math.BigDecimal;
import java.math.BigInteger;

public class NumberUtilsCreateNumberTest {

    @Test
    public void testCreateNumberNull() {
        assertNull(NumberUtils.createNumber(null)); // from Javadoc
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberBlank() {
        NumberUtils.createNumber("");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberWhitespace() {
        NumberUtils.createNumber("   ");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberDoubleDash() {
        NumberUtils.createNumber("--123");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberMalformed() {
        NumberUtils.createNumber("123.45.6");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberInvalidHex() {
        NumberUtils.createNumber("0xG");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberInvalidSuffix() {
        NumberUtils.createNumber("123Z");
    }

    @Test
    public void testCreateNumberInteger() {
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
        assertEquals(Integer.valueOf(-456), NumberUtils.createNumber("-456"));
        assertEquals(Integer.valueOf(0), NumberUtils.createNumber("0"));
        assertEquals(Integer.valueOf(Integer.MAX_VALUE), NumberUtils.createNumber(String.valueOf(Integer.MAX_VALUE)));
        assertEquals(Integer.valueOf(Integer.MIN_VALUE), NumberUtils.createNumber(String.valueOf(Integer.MIN_VALUE)));
    }

    @Test
    public void testCreateNumberLong() {
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123L"));
        assertEquals(Long.valueOf(-456L), NumberUtils.createNumber("-456l"));
        assertEquals(Long.valueOf(Integer.MAX_VALUE + 1L), NumberUtils.createNumber(String.valueOf(Integer.MAX_VALUE + 1L)));
        assertEquals(Long.valueOf(Long.MAX_VALUE), NumberUtils.createNumber(String.valueOf(Long.MAX_VALUE)));
        assertEquals(Long.valueOf(Long.MIN_VALUE), NumberUtils.createNumber(String.valueOf(Long.MIN_VALUE)));
    }

    @Test
    public void testCreateNumberFloat() {
        assertEquals(Float.valueOf(123.45f), NumberUtils.createNumber("123.45f"));
        assertEquals(Float.valueOf(-67.89F), NumberUtils.createNumber("-67.89F"));
        assertEquals(Float.valueOf(0.0f), NumberUtils.createNumber("0.0f"));
        assertEquals(Float.valueOf(Float.MAX_VALUE), NumberUtils.createNumber(String.valueOf(Float.MAX_VALUE)));
        assertEquals(Float.valueOf(Float.MIN_NORMAL), NumberUtils.createNumber(String.valueOf(Float.MIN_NORMAL)));
        assertEquals(Float.valueOf(Float.POSITIVE_INFINITY), NumberUtils.createNumber("1e40f")); // Overflow to infinity
        assertEquals(Float.valueOf(Float.NEGATIVE_INFINITY), NumberUtils.createNumber("-1e40f")); // Underflow to negative infinity
        assertEquals(Float.valueOf(0.0f), NumberUtils.createNumber("1e-50f")); // Underflow to zero
    }

    @Test
    public void testCreateNumberDouble() {
        assertEquals(Double.valueOf(123.45), NumberUtils.createNumber("123.45"));
        assertEquals(Double.valueOf(-67.89), NumberUtils.createNumber("-67.89d"));
        assertEquals(Double.valueOf(0.0), NumberUtils.createNumber("0.0D"));
        assertEquals(Double.valueOf(Double.MAX_VALUE), NumberUtils.createNumber(String.valueOf(Double.MAX_VALUE)));
        assertEquals(Double.valueOf(Double.MIN_NORMAL), NumberUtils.createNumber(String.valueOf(Double.MIN_NORMAL)));
        assertEquals(Double.valueOf(Double.POSITIVE_INFINITY), NumberUtils.createNumber("1e309")); // Overflow to infinity
        assertEquals(Double.valueOf(Double.NEGATIVE_INFINITY), NumberUtils.createNumber("-1e309")); // Underflow to negative infinity
        assertEquals(Double.valueOf(0.0), NumberUtils.createNumber("1e-325")); // Underflow to zero
    }

    @Test
    public void testCreateNumberHexadecimal() {
        assertEquals(Integer.valueOf(255), NumberUtils.createNumber("0xFF"));
        assertEquals(Integer.valueOf(-16), NumberUtils.createNumber("-0x10"));
        assertEquals(Integer.valueOf(10), NumberUtils.createNumber("0xa"));
        assertEquals(Integer.valueOf(0), NumberUtils.createNumber("0x0"));
        assertEquals(Long.valueOf(0x7FFFFFFFFFFFFFFFL), NumberUtils.createNumber("0x7FFFFFFFFFFFFFFFL"));
        assertEquals(Long.valueOf(-0x8000000000000000L), NumberUtils.createNumber("-0x8000000000000000L"));
    }

    @Test
    public void testCreateNumberScientificNotation() {
        assertEquals(Double.valueOf(1.23e4), NumberUtils.createNumber("1.23e4"));
        assertEquals(Double.valueOf(-5.67E-8), NumberUtils.createNumber("-5.67E-8"));
        assertEquals(Float.valueOf(1.23e4f), NumberUtils.createNumber("1.23e4f"));
        assertEquals(Float.valueOf(-5.67E-8F), NumberUtils.createNumber("-5.67E-8F"));
        assertEquals(new BigDecimal("1.23456789012345678901234567890123456789E+100"), NumberUtils.createNumber("1.23456789012345678901234567890123456789E+100"));
    }

    @Test
    public void testCreateNumberBigInteger() {
        String bigIntStr = "123456789012345678901234567890";
        assertEquals(new BigInteger(bigIntStr), NumberUtils.createNumber(bigIntStr));
        String negativeBigIntStr = "-987654321098765432109876543210";
        assertEquals(new BigInteger(negativeBigIntStr), NumberUtils.createNumber(negativeBigIntStr));
        assertEquals(new BigInteger("0"), NumberUtils.createNumber("0"));
    }

    @Test
    public void testCreateNumberBigDecimal() {
        String bigDecimalStr = "12345678901234567890.12345678901234567890";
        assertEquals(new BigDecimal(bigDecimalStr), NumberUtils.createNumber(bigDecimalStr));
        String negativeBigDecimalStr = "-98765432109876543210.98765432109876543210";
        assertEquals(new BigDecimal(negativeBigDecimalStr), NumberUtils.createNumber(negativeBigDecimalStr));
        assertEquals(new BigDecimal("0.0"), NumberUtils.createNumber("0.0"));

        // Test for precision loss promotion to BigDecimal
        // A double that cannot be represented exactly by float
        String doublePrecisionStr = "1.0000000000000001";
        assertTrue(NumberUtils.createNumber(doublePrecisionStr) instanceof BigDecimal);
        assertEquals(new BigDecimal(doublePrecisionStr), NumberUtils.createNumber(doublePrecisionStr));

        // A float that would lose precision if parsed as double (not directly applicable as float is smaller)
        // The logic is more about double/float not being able to represent the value exactly, leading to BigDecimal
        String verySmallFloatStr = "1.23456789012345678901234567890123456789e-40f"; // Should be float
        assertEquals(Float.valueOf(verySmallFloatStr.substring(0, verySmallFloatStr.length() - 1)), NumberUtils.createNumber(verySmallFloatStr));

        String veryLargeFloatStr = "1.23456789012345678901234567890123456789e+30f"; // Should be float
        assertEquals(Float.valueOf(veryLargeFloatStr.substring(0, veryLargeFloatStr.length() - 1)), NumberUtils.createNumber(veryLargeFloatStr));

        // Test for numbers that would result in infinity or zero due to precision loss when parsed as Float or Double
        // and are automatically promoted to BigDecimal.
        // This is a bit tricky as Java's Double.parseDouble already handles this.
        // The docstring implies a custom check. Let's test a number that is too large for Double but not for BigDecimal.
        String tooLargeForDouble = "1.7976931348623157E+3080"; // Larger than Double.MAX_VALUE
        assertTrue(NumberUtils.createNumber(tooLargeForDouble) instanceof BigDecimal);
        assertEquals(new BigDecimal(tooLargeForDouble), NumberUtils.createNumber(tooLargeForDouble));

        String tooSmallForDouble = "4.9E-3240"; // Smaller than Double.MIN_VALUE
        assertTrue(NumberUtils.createNumber(tooSmallForDouble) instanceof BigDecimal);
        assertEquals(new BigDecimal(tooSmallForDouble), NumberUtils.createNumber(tooSmallForDouble));
    }

    @Test
    public void testCreateNumberNoSuffixPrecision() {
        // Test that without suffix, it tries integer types first, then floating point.
        // A number that fits in Integer
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
        // A number that fits in Long but not Integer
        assertEquals(Long.valueOf(Integer.MAX_VALUE + 1L), NumberUtils.createNumber(String.valueOf(Integer.MAX_VALUE + 1L)));
        // A number that fits in Float but not Long
        assertEquals(Float.valueOf(123.45f), NumberUtils.createNumber("123.45")); // Should be Double by default, but if it fits float, it might be float.
        // The docstring says "prioritizes smaller, more precise types first".
        // For "123.45", it should be Double, not Float, as Double is more precise.
        assertEquals(Double.valueOf(123.45), NumberUtils.createNumber("123.45"));

        // A number that fits in Double but not Float
        String doubleOnly = "1.2345678901234567"; // More precision than float can hold
        assertTrue(NumberUtils.createNumber(doubleOnly) instanceof Double);
        assertEquals(Double.valueOf(doubleOnly), NumberUtils.createNumber(doubleOnly));

        // A number that requires BigDecimal
        String bigDecimalRequired = "123456789012345678901234567890.123456789012345678901234567890";
        assertTrue(NumberUtils.createNumber(bigDecimalRequired) instanceof BigDecimal);
        assertEquals(new BigDecimal(bigDecimalRequired), NumberUtils.createNumber(bigDecimalRequired));
    }

    @Test
    public void testCreateNumberEdgeCases() {
        assertEquals(Integer.valueOf(0), NumberUtils.createNumber("0"));
        assertEquals(Double.valueOf(0.0), NumberUtils.createNumber("0.0"));
        assertEquals(Float.valueOf(0.0f), NumberUtils.createNumber("0.0f"));
        assertEquals(Long.valueOf(0L), NumberUtils.createNumber("0L"));
        assertEquals(new BigInteger("0"), NumberUtils.createNumber("0x0"));
        assertEquals(new BigDecimal("0.0"), NumberUtils.createNumber("0.0D"));
    }

    @Test
    public void testCreateNumberWithLeadingZeros() {
        // Leading zeros are not interpreted as octal
        assertEquals(Integer.valueOf(10), NumberUtils.createNumber("010"));
        assertEquals(Long.valueOf(10L), NumberUtils.createNumber("010L"));
        assertEquals(Double.valueOf(10.0), NumberUtils.createNumber("010.0"));
    }

    @Test
    public void testCreateNumberNegativeHexadecimal() {
        assertEquals(Integer.valueOf(-1), NumberUtils.createNumber("-0x1"));
        assertEquals(Long.valueOf(-1L), NumberUtils.createNumber("-0x1L"));
    }

    @Test
    public void testCreateNumberFloatDoubleSuffixes() {
        assertEquals(Float.valueOf("1.23"), NumberUtils.createNumber("1.23f"));
        assertEquals(Float.valueOf("1.23"), NumberUtils.createNumber("1.23F"));
        assertEquals(Double.valueOf("1.23"), NumberUtils.createNumber("1.23d"));
        assertEquals(Double.valueOf("1.23"), NumberUtils.createNumber("1.23D"));
    }

    @Test
    public void testCreateNumberLongSuffixes() {
        assertEquals(Long.valueOf("123"), NumberUtils.createNumber("123l"));
        assertEquals(Long.valueOf("123"), NumberUtils.createNumber("123L"));
    }

    @Test
    public void testCreateNumberNoSuffixIntegerRange() {
        // Test that numbers within Integer.MAX_VALUE are parsed as Integer
        assertEquals(Integer.valueOf(12345), NumberUtils.createNumber("12345"));
        // Test that numbers exceeding Integer.MAX_VALUE but within Long.MAX_VALUE are parsed as Long
        assertEquals(Long.valueOf(2147483648L), NumberUtils.createNumber("2147483648"));
    }

    @Test
    public void testCreateNumberNoSuffixFloatingPointRange() {
        // Test a simple decimal without suffix, should be Double
        assertEquals(Double.valueOf(123.45), NumberUtils.createNumber("123.45"));
        // Test a scientific notation without suffix, should be Double
        assertEquals(Double.valueOf(1.23e-5), NumberUtils.createNumber("1.23e-5"));
    }

    @Test
    public void testCreateNumberBigDecimalFromVeryLongDecimal() {
        String veryLongDecimal = "1234567890123456789012345678901234567890.1234567890123456789012345678901234567890";
        assertTrue(NumberUtils.createNumber(veryLongDecimal) instanceof BigDecimal);
        assertEquals(new BigDecimal(veryLongDecimal), NumberUtils.createNumber(veryLongDecimal));
    }

    @Test
    public void testCreateNumberBigIntegerFromVeryLongInteger() {
        String veryLongInteger = "12345678901234567890123456789012345678901234567890";
        assertTrue(NumberUtils.createNumber(veryLongInteger) instanceof BigInteger);
        assertEquals(new BigInteger(veryLongInteger), NumberUtils.createNumber(veryLongInteger));
    }
