        org.apache.commons.lang3.math.NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_Integer() {
        Number num = org.apache.commons.lang3.math.NumberUtils.createNumber("123");
        assertTrue(num instanceof Integer);
        assertEquals(Integer.valueOf(123), num);

        num = org.apache.commons.lang3.math.NumberUtils.createNumber("-456");
        assertTrue(num instanceof Integer);
        assertEquals(Integer.valueOf(-456), num);

        num = org.apache.commons.lang3.math.NumberUtils.createNumber("0");
        assertTrue(num instanceof Integer);
        assertEquals(Integer.valueOf(0), num);
    }

    @Test
    public void testCreateNumber_Long() {
        Number num = org.apache.commons.lang3.math.NumberUtils.createNumber("1234567890123");
        assertTrue(num instanceof Long);
        assertEquals(Long.valueOf(1234567890123L), num);

        num = org.apache.commons.lang3.math.NumberUtils.createNumber("-9876543210987L");
        assertTrue(num instanceof Long);
        assertEquals(Long.valueOf(-9876543210987L), num);

        num = org.apache.commons.lang3.math.NumberUtils.createNumber(String.valueOf(Integer.MAX_VALUE) + "1"); // Exceeds Integer.MAX_VALUE
        assertTrue(num instanceof Long);
        assertEquals(Long.valueOf(Integer.MAX_VALUE + 1L), num);
    }

    @Test
    public void testCreateNumber_BigInteger() {
        String bigIntStr = "123456789012345678901234567890";
        Number num = org.apache.commons.lang3.math.NumberUtils.createNumber(bigIntStr);
        assertTrue(num instanceof BigInteger);
        assertEquals(new BigInteger(bigIntStr), num);

        String bigIntStrL = "92233720368547758071L"; // Exceeds Long.MAX_VALUE
        num = org.apache.commons.lang3.math.NumberUtils.createNumber(bigIntStrL);
        assertTrue(num instanceof BigInteger);
        assertEquals(new BigInteger(bigIntStrL.substring(0, bigIntStrL.length() - 1)), num);
    }

