public class StringUtilsJoinTest {

    @Test
    public void testJoin_NullArray() {
        // R3: Returns null if the input array is null.
        assertNull(StringUtils.join(null, ',', 0, 0));
    }

    @Test
    public void testJoin_EmptyArray() {
        // R3: Returns an empty string ("") if the effective range is empty.
        assertEquals("", StringUtils.join(new Object[]{}, ',', 0, 0));
    }

    @Test
    public void testJoin_SingleElementArray() {
        Object[] array = {"a"};
        // R2: Agreement with overload join(Object[] array, char separator)
        assertEquals(StringUtils.join(array, ','), StringUtils.join(array, ',', 0, array.length));
        assertEquals("a", StringUtils.join(array, ',', 0, 1));
    }

    @Test
    public void testJoin_MultipleElements() {
        Object[] array = {"a", "b", "c"};
        // R2: Agreement with overload join(Object[] array, char separator)
        assertEquals(StringUtils.join(array, ';'), StringUtils.join(array, ';', 0, array.length));
        assertEquals("a;b;c", StringUtils.join(array, ';', 0, 3)); // from Javadoc
    }

