        Calendar cal2 = new GregorianCalendar(2023, Calendar.JANUARY, 1, 11, 30, 45);
        cal2.set(Calendar.MILLISECOND, 123);
        assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
