import org.apache.commons.lang3.math.NumberUtils;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtilsIsNumberTest {

    @Test
    public void testIsNumber_R3_NullAndEmptyStrings() {
        // R3: Null and empty String will return false.
        assertFalse(NumberUtils.isNumber(null));
        assertFalse(NumberUtils.isNumber(""));
    }

    @Test
    public void testIsNumber_R4_StandardIntegers() {
        // R4: Standard integers should be recognized.
        assertTrue(NumberUtils.isNumber("123"));
        assertTrue(NumberUtils.isNumber("-45"));
        assertTrue(NumberUtils.isNumber("0"));
        assertTrue(NumberUtils.isNumber("+100")); // Although not explicitly mentioned, common numeric parsing handles this.
    }

    @Test
    public void testIsNumber_R4_DecimalNumbers() {
        // R4: Decimal numbers should be recognized.
        assertTrue(NumberUtils.isNumber("1.23"));
        assertTrue(NumberUtils.isNumber("-0.5"));
        assertTrue(NumberUtils.isNumber("123."));
        assertTrue(NumberUtils.isNumber(".5"));
        assertTrue(NumberUtils.isNumber("0.0"));
        assertTrue(NumberUtils.isNumber("-1.0"));
    }

    @Test
    public void testIsNumber_R4_ScientificNotation() {
        // R4: Scientific notation should be recognized.
        assertTrue(NumberUtils.isNumber("1.2e-3"));
        assertTrue(NumberUtils.isNumber("1E+5"));
        assertTrue(NumberUtils.isNumber("1e5"));
        assertTrue(NumberUtils.isNumber("-1.23E-4"));
        assertTrue(NumberUtils.isNumber("1.E1"));
        assertTrue(NumberUtils.isNumber(".1E1"));
    }

    @Test
    public void testIsNumber_R4_HexadecimalNumbers() {
        // R4: Hexadecimal numbers should be recognized.
        assertTrue(NumberUtils.isNumber("0xFE"));
        assertTrue(NumberUtils.isNumber("-0x1A"));
        assertTrue(NumberUtils.isNumber("0XFF"));
        assertTrue(NumberUtils.isNumber("0x0"));
    }

    @Test
    public void testIsNumber_R4_NumbersWithTypeQualifiers() {
        // R4: Numbers with type qualifiers should be recognized.
        assertTrue(NumberUtils.isNumber("123L"));
        assertTrue(NumberUtils.isNumber("4.5F"));
        assertTrue(NumberUtils.isNumber("7.8D"));
        assertTrue(NumberUtils.isNumber("-10l"));
        assertTrue(NumberUtils.isNumber("1.0f"));
        assertTrue(NumberUtils.isNumber("2.0d"));
        assertTrue(NumberUtils.isNumber("123.F"));
        assertTrue(NumberUtils.isNumber("123.D"));
        assertTrue(NumberUtils.isNumber(".5F"));
        assertTrue(NumberUtils.isNumber(".5D"));
        assertTrue(NumberUtils.isNumber("1e5F"));
        assertTrue(NumberUtils.isNumber("1e5D"));
    }

    @Test
    public void testIsNumber_R4_SpecialFloatingPointValues() {
        // R4: Special floating-point values should be recognized (case-insensitive).
        assertTrue(NumberUtils.isNumber("Infinity"));
        assertTrue(NumberUtils.isNumber("-Infinity"));
        assertTrue(NumberUtils.isNumber("NaN"));
        assertTrue(NumberUtils.isNumber("infinity"));
        assertTrue(NumberUtils.isNumber("-infinity"));
        assertTrue(NumberUtils.isNumber("nan"));
        assertTrue(NumberUtils.isNumber("INFINITY"));
        assertTrue(NumberUtils.isNumber("-INFINITY"));
        assertTrue(NumberUtils.isNumber("NAN"));
    }

    @Test
    public void testIsNumber_R4_InvalidNumbers() {
        // R4: Strings that are not valid numbers should return false.
        assertFalse(NumberUtils.isNumber("abc"));
        assertFalse(NumberUtils.isNumber("123a"));
        assertFalse(NumberUtils.isNumber("1.2.3"));
        assertFalse(NumberUtils.isNumber("0xG")); // Invalid hex digit
        assertFalse(NumberUtils.isNumber("123L.")); // Qualifier then decimal point
        assertFalse(NumberUtils.isNumber("123.L")); // Decimal point then qualifier
        assertFalse(NumberUtils.isNumber("123e")); // Incomplete scientific notation
        assertFalse(NumberUtils.isNumber("e123")); // Starts with 'e'
        assertFalse(NumberUtils.isNumber("--1"));
        assertFalse(NumberUtils.isNumber("++1"));
        assertFalse(NumberUtils.isNumber("1-"));
        assertFalse(NumberUtils.isNumber("1+"));
        assertFalse(NumberUtils.isNumber("InfinityL")); // Qualifier after special value
        assertFalse(NumberUtils.isNumber("NaNF"));
        assertFalse(NumberUtils.isNumber("0x")); // Incomplete hex
        assertFalse(NumberUtils.isNumber("0x-1")); // Sign after 0x
        assertFalse(NumberUtils.isNumber("0xFE.")); // Hex with decimal
        assertFalse(NumberUtils.isNumber("123 456")); // Space in number
        assertFalse(NumberUtils.isNumber(" 123")); // Leading space
        assertFalse(NumberUtils.isNumber("123 ")); // Trailing space
        assertFalse(NumberUtils.isNumber(".")); // Just a decimal point
        assertFalse(NumberUtils.isNumber("-")); // Just a sign
        assertFalse(NumberUtils.isNumber("+")); // Just a sign
        assertFalse(NumberUtils.isNumber("e")); // Just 'e'
        assertFalse(NumberUtils.isNumber("E")); // Just 'E'
    }

