    public void testIsNumber_R4_EdgeCases() {
        // R4: Edge cases for various formats.
        assertTrue(NumberUtils.isNumber("0."));
        assertTrue(NumberUtils.isNumber(".0"));
        assertTrue(NumberUtils.isNumber("0e0"));
        assertTrue(NumberUtils.isNumber("0x1"));
        assertTrue(NumberUtils.isNumber("0L"));
        assertTrue(NumberUtils.isNumber("0F"));
        assertTrue(NumberUtils.isNumber("0D"));
        assertTrue(NumberUtils.isNumber("-0")); // Valid integer
        assertTrue(NumberUtils.isNumber("-0.0")); // Valid decimal
        assertTrue(NumberUtils.isNumber("-0e0")); // Valid scientific
