import org.apache.commons.lang3.text.translate.NumericEntityUnescaper;
import org.junit.Before;
import org.junit.Test;

import java.io.IOException;
import java.io.StringWriter;
import java.io.Writer;

import static org.junit.Assert.*;

public class NumericEntityUnescaperTest {

    private NumericEntityUnescaper unescaper;
    private Writer writer;

    @Before
    public void setUp() {
        unescaper = new NumericEntityUnescaper();
        writer = new StringWriter();
    }

    @Test(expected = IllegalArgumentException.class)
    public void testTranslateNullInput() throws IOException {
        unescaper.translate(null, 0, writer);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testTranslateNullWriter() throws IOException {
        unescaper.translate("&#123;", 0, null);
    }

    @Test
    public void testTranslateDecimalEntity() throws IOException {
        String input = "&#123;";
        int consumed = unescaper.translate(input, 0, writer);
        assertEquals(input.length(), consumed);
        assertEquals("{", writer.toString());

        writer = new StringWriter();
        input = "prefix&#65;suffix";
        consumed = unescaper.translate(input, 6, writer);
        assertEquals(5, consumed);
        assertEquals("A", writer.toString());
    }

    @Test
    public void testTranslateHexadecimalEntity() throws IOException {
        String input = "&#xFF;";
        int consumed = unescaper.translate(input, 0, writer);
        assertEquals(input.length(), consumed);
        assertEquals("ÿ", writer.toString());

        writer = new StringWriter();
        input = "prefix&#x41;suffix";
        consumed = unescaper.translate(input, 6, writer);
        assertEquals(6, consumed);
        assertEquals("A", writer.toString());
    }

    @Test
    public void testTranslateMixedCaseHexadecimalEntity() throws IOException {
        String input = "&#XfF;";
        int consumed = unescaper.translate(input, 0, writer);
        assertEquals(input.length(), consumed);
        assertEquals("ÿ", writer.toString());
    }

    @Test
    public void testTranslateInvalidIndex() throws IOException {
        String input = "&#123;";
        int consumed = unescaper.translate(input, input.length(), writer);
        assertEquals(0, consumed);
        assertEquals("", writer.toString());

        writer = new StringWriter();
        consumed = unescaper.translate(input, -1, writer);
        assertEquals(0, consumed);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslateNoEntityAtGivenIndex() throws IOException {
        String input = "abc&#123;";
        int consumed = unescaper.translate(input, 1, writer);
        assertEquals(0, consumed);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslateIncompleteDecimalEntity() throws IOException {
        String input = "&#123";
        int consumed = unescaper.translate(input, 0, writer);
        assertEquals(0, consumed);
        assertEquals("", writer.toString());

        writer = new StringWriter();
        input = "&#";
        consumed = unescaper.translate(input, 0, writer);
        assertEquals(0, consumed);
        assertEquals("", writer.toString());

        writer = new StringWriter();
        input = "&";
        consumed = unescaper.translate(input, 0, writer);
        assertEquals(0, consumed);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslateIncompleteHexadecimalEntity() throws IOException {
        String input = "&#xFF";
        int consumed = unescaper.translate(input, 0, writer);
        assertEquals(0, consumed);
        assertEquals("", writer.toString());

        writer = new StringWriter();
        input = "&#x";
        consumed = unescaper.translate(input, 0, writer);
        assertEquals(0, consumed);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslateNonNumericContent() throws IOException {
        String input = "&#abc;";
        int consumed = unescaper.translate(input, 0, writer);
        assertEquals(0, consumed);
        assertEquals("", writer.toString());

        writer = new StringWriter();
        input = "&#xG;";
        consumed = unescaper.translate(input, 0, writer);
        assertEquals(0, consumed);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslateMissingSemicolon() throws IOException {
        String input = "&#123";
        int consumed = unescaper.translate(input, 0, writer);
        assertEquals(0, consumed);
        assertEquals("", writer.toString());

        writer = new StringWriter();
        input = "&#x41";
        consumed = unescaper.translate(input, 0, writer);
        assertEquals(0, consumed);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslateEmptyString() throws IOException {
        String input = "";
        int consumed = unescaper.translate(input, 0, writer);
        assertEquals(0, consumed);
        assertEquals("", writer.toString());
    }

    @Test
    public void testTranslateLargeDecimalValue() throws IOException {
        String input = "&#65535;"; // U+FFFF
        int consumed = unescaper.translate(input, 0, writer);
        assertEquals(input.length(), consumed);
        assertEquals(String.valueOf((char) 65535), writer.toString());
    }

    @Test
    public void testTranslateLargeHexadecimalValue() throws IOException {
        String input = "&#xFFFF;"; // U+FFFF
        int consumed = unescaper.translate(input, 0, writer);
        assertEquals(input.length(), consumed);
        assertEquals(String.valueOf((char) 0xFFFF), writer.toString());
    }

    @Test
    public void testTranslateSupplementaryCharacterDecimal() throws IOException {
        // &#128512; is U+1F600 (Grinning Face emoji)
