        assertEquals(input.length(), consumed);
        assertEquals("\uD83D\uDE00", writer.toString()); // Surrogate pair
    }

    @Test
    public void testTranslateMultipleEntities() throws IOException {
        String input = "Hello&#32;World&#33;";
        int consumed1 = unescaper.translate(input, 5, writer);
        assertEquals(5, consumed1);
        assertEquals(" ", writer.toString());

        writer = new StringWriter();
        int consumed2 = unescaper.translate(input, 15, writer);
        assertEquals(5, consumed2);
        assertEquals("!", writer.toString());
    }

    @Test
    public void testTranslateEntityAtStart() throws IOException {
        String input = "&#65;BC";
        int consumed = unescaper.translate(input, 0, writer);
        assertEquals(5, consumed);
        assertEquals("A", writer.toString());
    }

    @Test
    public void testTranslateEntityAtEnd() throws IOException {
        String input = "AB&#67;";
        int consumed = unescaper.translate(input, 2, writer);
        assertEquals(5, consumed);
        assertEquals("C", writer.toString());
    }

    @Test
    public void testTranslateZeroValue() throws IOException {
        String input = "&#0;";
