import static org.junit.Assert.*;

public class StringUtilsIndexOfAnyButTest {

    private static final int INDEX_NOT_FOUND = StringUtils.INDEX_NOT_FOUND;

    @Test
    public void testIndexOfAnyBut_NullString() {
        // R3: If str is null, INDEX_NOT_FOUND is returned.
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut(null, "abc"));
    }

    @Test
    public void testIndexOfAnyBut_EmptyString() {
        // R3: If str is empty, INDEX_NOT_FOUND is returned.
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("", "abc"));
    }

    @Test
    public void testIndexOfAnyBut_NullSearchChars() {
        // R3: If searchChars is null, INDEX_NOT_FOUND is returned.
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("abc", null));
    }

    @Test
    public void testIndexOfAnyBut_EmptySearchChars() {
        // R3: If searchChars is empty, and str is not empty, the method returns 0.
        assertEquals(0, StringUtils.indexOfAnyBut("abc", ""));
        // from Javadoc
        assertEquals(0, StringUtils.indexOfAnyBut("zzabyycdxx", ""));
    }

    @Test
    public void testIndexOfAnyBut_AllCharsInSearchChars() {
        // R3: If all characters in str are found within searchChars, INDEX_NOT_FOUND is returned.
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("abc", "abc"));
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("aaa", "a"));
        // from Javadoc
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("aba", "ab"));
    }

    @Test
    public void testIndexOfAnyBut_FirstCharNotInSearchChars() {
        // R4: If the first character of str is not in searchChars, the method should return 0.
        assertEquals(0, StringUtils.indexOfAnyBut("abc", "bc"));
        assertEquals(0, StringUtils.indexOfAnyBut("xyz", "yz"));
    }

    @Test
    public void testIndexOfAnyBut_MiddleCharNotInSearchChars() {
        // R4: Test with a character in the middle of the string not being in searchChars.
        assertEquals(1, StringUtils.indexOfAnyBut("aBc", "ac"));
        assertEquals(2, StringUtils.indexOfAnyBut("abCde", "abde"));
        // from Javadoc
        assertEquals(3, StringUtils.indexOfAnyBut("zzabyycdxx", "za"));
    }

    @Test
    public void testIndexOfAnyBut_LastCharNotInSearchChars() {
        // R4: Test with the last character of the string not being in searchChars.
        assertEquals(2, StringUtils.indexOfAnyBut("abC", "ab"));
        assertEquals(4, StringUtils.indexOfAnyBut("abcdeF", "abcde"));
    }

    @Test
    public void testIndexOfAnyBut_NoMatch() {
        // R3: If no such character is found, INDEX_NOT_FOUND is returned.
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("hello", "olleh"));
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("12345", "54321"));
    }

    @Test
    public void testIndexOfAnyBut_SingleCharString() {
        // R4: Test with a single character string.
        assertEquals(0, StringUtils.indexOfAnyBut("a", ""));
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("a", "a"));
        assertEquals(0, StringUtils.indexOfAnyBut("a", "b"));
    }

    @Test
    public void testIndexOfAnyBut_SingleCharSearchChars() {
        // R4: Test with a single character searchChars.
        assertEquals(1, StringUtils.indexOfAnyBut("abc", "a"));
        assertEquals(0, StringUtils.indexOfAnyBut("abc", "x"));
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("aaa", "a"));
    }

    @Test
    public void testIndexOfAnyBut_OverloadAgreement() {
        // R2: Agreement between overloads.
        // The CharSequence overload with char[] should produce the same result.
        String str = "testString";
        String searchCharsStr = "ts";
        char[] searchCharsArray = searchCharsStr.toCharArray();

        assertEquals(StringUtils.indexOfAnyBut(str, searchCharsStr),
                StringUtils.indexOfAnyBut((CharSequence) str, searchCharsArray));

        str = "anotherExample";
        searchCharsStr = "ae";
        searchCharsArray = searchCharsStr.toCharArray();
        assertEquals(StringUtils.indexOfAnyBut(str, searchCharsStr),
                StringUtils.indexOfAnyBut((CharSequence) str, searchCharsArray));

        str = "allmatch";
        searchCharsStr = "ahlmtc";
        searchCharsArray = searchCharsStr.toCharArray();
        assertEquals(StringUtils.indexOfAnyBut(str, searchCharsStr),
                StringUtils.indexOfAnyBut((CharSequence) str, searchCharsArray));

        str = "nomatch";
        searchCharsStr = "xyz";
        searchCharsArray = searchCharsStr.toCharArray();
        assertEquals(StringUtils.indexOfAnyBut(str, searchCharsStr),
                StringUtils.indexOfAnyBut((CharSequence) str, searchCharsArray));
    }

    @Test
    public void testIndexOfAnyBut_WithSpecialCharacters() {
        // R4: Test with special characters.
        assertEquals(0, StringUtils.indexOfAnyBut("!@#$", "@#$"));
        assertEquals(1, StringUtils.indexOfAnyBut("a-b", "ab"));
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut("!@#", "!@#"));
    }

    @Test
    public void testIndexOfAnyBut_LongStrings() {
        // R4: Test with longer strings to ensure performance and correctness.
        String longStr = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
        String searchChars = "abcdefghijklmnopqrstuvwxyz";
        assertEquals(26, StringUtils.indexOfAnyBut(longStr, searchChars));

        searchChars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
        assertEquals(INDEX_NOT_FOUND, StringUtils.indexOfAnyBut(longStr, searchChars));

        searchChars = "";
        assertEquals(0, StringUtils.indexOfAnyBut(longStr, searchChars));
    }
}
