import org.junit.Test;
import static org.junit.Assert.*;
import org.apache.commons.lang3.StringUtils;

public class StringUtilsContainsNoneTest {

    @Test
    public void testContainsNone_NullCharSequence() {
        char[] searchChars = {'a', 'b'};
        assertTrue(StringUtils.containsNone(null, searchChars)); // from Javadoc
    }

    @Test
    public void testContainsNone_NullSearchChars() {
        CharSequence cs = "abc";
        assertTrue(StringUtils.containsNone(cs, null)); // from Javadoc
    }

    @Test
    public void testContainsNone_EmptyCharSequence() {
        char[] searchChars = {'a', 'b'};
        assertTrue(StringUtils.containsNone("", searchChars)); // from Javadoc
    }

    @Test
    public void testContainsNone_EmptySearchChars() {
        CharSequence cs = "abc";
        assertTrue(StringUtils.containsNone(cs, new char[]{})); // from Javadoc
    }

    @Test
    public void testContainsNone_NoMatch() {
        CharSequence cs = "abab";
        char[] searchChars = {'x', 'y', 'z'};
        assertTrue(StringUtils.containsNone(cs, searchChars)); // from Javadoc
        assertTrue(StringUtils.containsNone(cs, new char[]{'1', '2', '3'}));
    }

    @Test
    public void testContainsNone_NoMatchWithNumbers() {
        CharSequence cs = "ab1";
        char[] searchChars = {'x', 'y', 'z'};
        assertTrue(StringUtils.containsNone(cs, searchChars)); // from Javadoc
    }

    @Test
    public void testContainsNone_WithMatch() {
        CharSequence cs = "abz";
        char[] searchChars = {'x', 'y', 'z'};
        assertFalse(StringUtils.containsNone(cs, searchChars)); // from Javadoc
        assertFalse(StringUtils.containsNone("hello", new char[]{'o'}));
        assertFalse(StringUtils.containsNone("world", new char[]{'w', 'r'}));
    }

    @Test
    public void testContainsNone_SingleCharCharSequence() {
        CharSequence cs = "a";
        char[] searchChars = {'b', 'c'};
        assertTrue(StringUtils.containsNone(cs, searchChars));
        assertFalse(StringUtils.containsNone(cs, new char[]{'a', 'c'}));
    }

    @Test
    public void testContainsNone_SingleCharSearchChars() {
        CharSequence cs = "abc";
        char[] searchChars = {'b'};
        assertFalse(StringUtils.containsNone(cs, searchChars));
        assertTrue(StringUtils.containsNone(cs, new char[]{'x'}));
    }

    @Test
    public void testContainsNone_OverloadAgreement_NoMatch() {
        CharSequence cs = "test";
        String invalidCharsString = "xyz";
        char[] invalidCharsArray = invalidCharsString.toCharArray();
        assertEquals(StringUtils.containsNone(cs, invalidCharsString), StringUtils.containsNone(cs, invalidCharsArray));
    }

    @Test
    public void testContainsNone_OverloadAgreement_WithMatch() {
        CharSequence cs = "test";
        String invalidCharsString = "set";
        char[] invalidCharsArray = invalidCharsString.toCharArray();
        assertEquals(StringUtils.containsNone(cs, invalidCharsString), StringUtils.containsNone(cs, invalidCharsArray));
    }

    @Test
    public void testContainsNone_OverloadAgreement_NullInvalidChars() {
        CharSequence cs = "test";
        String invalidCharsString = null;
        char[] invalidCharsArray = null;
        assertEquals(StringUtils.containsNone(cs, invalidCharsString), StringUtils.containsNone(cs, invalidCharsArray));
    }

    @Test
    public void testContainsNone_OverloadAgreement_EmptyInvalidChars() {
        CharSequence cs = "test";
        String invalidCharsString = "";
        char[] invalidCharsArray = invalidCharsString.toCharArray();
        assertEquals(StringUtils.containsNone(cs, invalidCharsString), StringUtils.containsNone(cs, invalidCharsArray));
    }

    @Test
    public void testContainsNone_ComplementaryToContainsAny() {
        CharSequence cs = "hello";
        char[] searchChars = {'h', 'e'};
        assertEquals(!StringUtils.containsAny(cs, searchChars), StringUtils.containsNone(cs, searchChars));

        char[] noMatchChars = {'x', 'y'};
        assertEquals(!StringUtils.containsAny(cs, noMatchChars), StringUtils.containsNone(cs, noMatchChars));
    }

    @Test
    public void testContainsNone_ComplementaryToContainsAny_EmptyCs() {
        CharSequence cs = "";
        char[] searchChars = {'h', 'e'};
        assertEquals(!StringUtils.containsAny(cs, searchChars), StringUtils.containsNone(cs, searchChars));
    }

    @Test
    public void testContainsNone_ComplementaryToContainsAny_NullCs() {
        CharSequence cs = null;
        char[] searchChars = {'h', 'e'};
        assertEquals(!StringUtils.containsAny(cs, searchChars), StringUtils.containsNone(cs, searchChars));
    }

    @Test
    public void testContainsNone_ComplementaryToContainsAny_NullSearchChars() {
        CharSequence cs = "hello";
        char[] searchChars = null;
        assertEquals(!StringUtils.containsAny(cs, searchChars), StringUtils.containsNone(cs, searchChars));
    }

    @Test
    public void testContainsNone_LongCharSequence() {
        CharSequence cs = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
        char[] searchChars = {'!', '@', '#', '$'};
        assertTrue(StringUtils.containsNone(cs, searchChars));

        char[] searchCharsWithMatch = {'a', 'Z', '5'};
        assertFalse(StringUtils.containsNone(cs, searchCharsWithMatch));
    }

    @Test
    public void testContainsNone_SpecialCharacters() {
        CharSequence cs = "!@#$%^&*()";
        char[] searchChars = {'a', 'b', 'c'};
        assertTrue(StringUtils.containsNone(cs, searchChars));

        char[] searchCharsWithMatch = {'%', '&'};
        assertFalse(StringUtils.containsNone(cs, searchCharsWithMatch));
    }
}
