import org.apache.commons.lang3.StringUtils;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtilsContainsAnyTest {

    @Test
    public void testContainsAny_NullCharSequence() {
        // R3: A null CharSequence will return false.
        assertFalse(StringUtils.containsAny(null, new char[]{'a', 'b'}));
        assertFalse(StringUtils.containsAny(null, null));
        assertFalse(StringUtils.containsAny(null, new char[]{}));
    }

    @Test
    public void testContainsAny_EmptyCharSequence() {
        // R3: An empty CharSequence will return false.
        assertFalse(StringUtils.containsAny("", new char[]{'a', 'b'}));
        assertFalse(StringUtils.containsAny("", null));
        assertFalse(StringUtils.containsAny("", new char[]{}));
    }

    @Test
    public void testContainsAny_NullSearchChars() {
        // R3: A null search array will return false.
        assertFalse(StringUtils.containsAny("abc", null));
        assertFalse(StringUtils.containsAny("", null));
        assertFalse(StringUtils.containsAny(null, null));
    }

    @Test
    public void testContainsAny_EmptySearchChars() {
        // R3: A zero length search array will return false.
        assertFalse(StringUtils.containsAny("abc", new char[]{}));
        assertFalse(StringUtils.containsAny("", new char[]{}));
        assertFalse(StringUtils.containsAny(null, new char[]{}));
    }

    @Test
    public void testContainsAny_ContainsOneChar() {
        // R4: If a character is present, adding more characters to searchChars should still return true.
        assertTrue(StringUtils.containsAny("abc", new char[]{'a'}));
        assertTrue(StringUtils.containsAny("abc", new char[]{'a', 'x'})); // from Javadoc
        assertTrue(StringUtils.containsAny("abc", new char[]{'b'}));
        assertTrue(StringUtils.containsAny("abc", new char[]{'c'}));
    }

    @Test
    public void testContainsAny_ContainsMultipleChars() {
        // R4: If multiple characters are present, the result should be true.
        assertTrue(StringUtils.containsAny("abc", new char[]{'a', 'b'})); // from Javadoc
        assertTrue(StringUtils.containsAny("zzabyycdxx", new char[]{'z', 'a'})); // from Javadoc
        assertTrue(StringUtils.containsAny("zzabyycdxx", new char[]{'b', 'y'})); // from Javadoc
    }

    @Test
    public void testContainsAny_DoesNotContainAnyChar() {
        // R4: If no characters are present, adding more non-matching characters should still return false.
        assertFalse(StringUtils.containsAny("abc", new char[]{'x'}));
        assertFalse(StringUtils.containsAny("abc", new char[]{'x', 'y'})); // from Javadoc
        assertFalse(StringUtils.containsAny("aba", new char[]{'z'})); // from Javadoc
    }

    @Test
    public void testContainsAny_FullMatch() {
        // R4: If all characters in cs are in searchChars, it should return true.
        assertTrue(StringUtils.containsAny("abc", new char[]{'a', 'b', 'c', 'd'}));
    }

    @Test
    public void testContainsAny_CaseSensitivity() {
        // R4: The method should be case-sensitive.
        assertFalse(StringUtils.containsAny("abc", new char[]{'A'}));
        assertTrue(StringUtils.containsAny("ABC", new char[]{'A'}));
        assertTrue(StringUtils.containsAny("aBc", new char[]{'B'}));
    }

    @Test
    public void testContainsAny_WithSpecialCharacters() {
        // R4: Test with special characters.
        assertTrue(StringUtils.containsAny("!@#$", new char[]{'@'}));
        assertFalse(StringUtils.containsAny("!@#$", new char[]{'%'}));
        assertTrue(StringUtils.containsAny("hello world", new char[]{' '}));
    }

    @Test
    public void testContainsAny_OverloadAgreement() {
        // R2: Agreement with containsAny(CharSequence cs, String searchChars) overload.
        String testString = "testString";
        char[] searchCharsArray = new char[]{'t', 'e'};
        String searchCharsString = "te";
        assertEquals(StringUtils.containsAny(testString, searchCharsArray), StringUtils.containsAny(testString, searchCharsString));

        searchCharsArray = new char[]{'x', 'y'};
        searchCharsString = "xy";
        assertEquals(StringUtils.containsAny(testString, searchCharsArray), StringUtils.containsAny(testString, searchCharsString));

        searchCharsArray = null;
        searchCharsString = null;
        assertEquals(StringUtils.containsAny(testString, searchCharsArray), StringUtils.containsAny(testString, searchCharsString));
    }

    @Test
    public void testContainsAny_ComplementaryWithContainsNone() {
        // R2: Complementary with containsNone(CharSequence cs, char[] invalidChars).
        String testString = "abcdef";
        char[] searchChars = new char[]{'a', 'x'};
        char[] invalidChars = new char[]{'a', 'x'};
        assertEquals(StringUtils.containsAny(testString, searchChars), !StringUtils.containsNone(testString, invalidChars));

        searchChars = new char[]{'x', 'y'};
        invalidChars = new char[]{'x', 'y'};
        assertEquals(StringUtils.containsAny(testString, searchChars), !StringUtils.containsNone(testString, invalidChars));

        // Test with nulls for containsNone
        assertFalse(StringUtils.containsAny(null, searchChars));
        assertTrue(StringUtils.containsNone(null, invalidChars)); // containsNone returns true for null cs

        assertFalse(StringUtils.containsAny(testString, null));
        assertTrue(StringUtils.containsNone(testString, null)); // containsNone returns true for null invalidChars
    }

    @Test
    public void testContainsAny_LongCharSequence() {
        // R4: Test with a longer CharSequence.
        String longString = "This is a very long string to test the containsAny method with various characters.";
        assertTrue(StringUtils.containsAny(longString, new char[]{'v', 'e', 'r', 'y'}));
        assertFalse(StringUtils.containsAny(longString, new char[]{'z', 'q', 'p'}));
        assertTrue(StringUtils.containsAny(longString, new char[]{' '}));
    }

    @Test
    public void testContainsAny_SingleCharCharSequence() {
        // R4: Test with a single character CharSequence.
        assertTrue(StringUtils.containsAny("a", new char[]{'a'}));
        assertFalse(StringUtils.containsAny("a", new char[]{'b'}));
        assertTrue(StringUtils.containsAny("a", new char[]{'a', 'b'}));
    }
}
