import org.apache.commons.lang3.ArrayUtils;
import org.apache.commons.lang3.ClassUtils;
import org.junit.Test;
import static org.junit.Assert.*;

public class ClassUtilsToClassTest {

    @Test
    public void testToClassNullArray() {
        // R3: If the input array is null, the method returns null.
        assertNull(ClassUtils.toClass(null));
    }

    @Test
    public void testToClassEmptyArray() {
        // R3: If the input array is empty, the method returns a pre-defined empty Class<?>[] array.
        assertEquals(ArrayUtils.EMPTY_CLASS_ARRAY, ClassUtils.toClass(new Object[]{}));
    }

    @Test
    public void testToClassWithVariousObjects() {
        Object[] input = {
            "hello",
            123,
            true,
            new Double(3.14),
            null,
            new ClassUtilsToClassTest(),
            new Integer(42)
        };

        Class<?>[] expectedClasses = {
            String.class,
            Integer.class,
            Boolean.class,
            Double.class,
            null,
            ClassUtilsToClassTest.class,
            Integer.class
        };

        Class<?>[] result = ClassUtils.toClass(input);

        // R3: The length of the returned array should be the same as the input array.
        assertEquals(input.length, result.length);

        // R3: For each non-null object, it retrieves its runtime class.
        // R3: If an element in the input array is null, the corresponding element in the returned array will also be null.
        for (int i = 0; i < input.length; i++) {
            assertEquals(expectedClasses[i], result[i]);
        }
