    @Test
    public void testAddObjectArrayAtIndex() {
        // R3: If the original array is null, a new array of size 1 will be created
        // with the component type inferred from the element.
        String[] result1 = ArrayUtils.add(null, 0, "a");
        assertNotNull(result1);
        assertEquals(1, result1.length);
        assertEquals("a", result1[0]);

        // R3: If the original array is null, a new array of size 1 will be created
        // with the component type inferred from the element.
        // R3: If both `array` and `element` are `null`, IllegalArgumentException is thrown.
        try {
            ArrayUtils.add(null, 0, null);
            fail("IllegalArgumentException expected for null array and null element");
        } catch (IllegalArgumentException e) {
            // Expected
        }

        // R3: The new array will be of the same component type as the original array.
        String[] originalArray = {"a", "b"};
        String[] result2 = ArrayUtils.add(originalArray, 1, "c");
        assertNotNull(result2);
        assertEquals(originalArray.getClass().getComponentType(), result2.getClass().getComponentType());
        assertEquals(originalArray.length + 1, result2.length);
        assertEquals("a", result2[0]);
        assertEquals("c", result2[1]);
