public class NumberUtilsIsNumberTest {

    @Test
    public void testIsNumber_ValidIntegers() {
        assertTrue(NumberUtils.isNumber("0"));
        assertTrue(NumberUtils.isNumber("123"));
        assertTrue(NumberUtils.isNumber("-45"));
        assertTrue(NumberUtils.isNumber("+67"));
        assertTrue(NumberUtils.isNumber("007"));
        assertTrue(NumberUtils.isNumber("123L"));
        assertTrue(NumberUtils.isNumber("-45l"));
    }

    @Test
    public void testIsNumber_ValidDecimals() {
        assertTrue(NumberUtils.isNumber("123.45"));
        assertTrue(NumberUtils.isNumber(".5"));
        assertTrue(NumberUtils.isNumber("1."));
        assertTrue(NumberUtils.isNumber("-1.23"));
        assertTrue(NumberUtils.isNumber("0.0"));
        assertTrue(NumberUtils.isNumber("1.23f"));
        assertTrue(NumberUtils.isNumber("4.5F"));
        assertTrue(NumberUtils.isNumber("6.7d"));
        assertTrue(NumberUtils.isNumber("8.9D"));
        assertTrue(NumberUtils.isNumber("-0.5f"));
    }

    @Test
    public void testIsNumber_ValidScientificNotation() {
        assertTrue(NumberUtils.isNumber("1.23e-4"));
        assertTrue(NumberUtils.isNumber("5E+2"));
        assertTrue(NumberUtils.isNumber("-1.2e3"));
        assertTrue(NumberUtils.isNumber("1e10"));
        assertTrue(NumberUtils.isNumber("1.23e-4f"));
        assertTrue(NumberUtils.isNumber("5E+2D"));
        assertTrue(NumberUtils.isNumber("0.1E-01"));
        assertTrue(NumberUtils.isNumber("123e4"));
    }

    @Test
    public void testIsNumber_ValidHexadecimal() {
        assertTrue(NumberUtils.isNumber("0xAF"));
        assertTrue(NumberUtils.isNumber("0X1a"));
        assertTrue(NumberUtils.isNumber("-0x10"));
        assertTrue(NumberUtils.isNumber("0x0"));
        assertTrue(NumberUtils.isNumber("0xabcdef"));
        assertTrue(NumberUtils.isNumber("0XABCDEF"));
    }

    @Test
    public void testIsNumber_InvalidInputs() {
        assertFalse(NumberUtils.isNumber(null)); // from Javadoc
        assertFalse(NumberUtils.isNumber("")); // from Javadoc
        assertFalse(NumberUtils.isNumber(" "));
        assertFalse(NumberUtils.isNumber("."));
        assertFalse(NumberUtils.isNumber("e"));
        assertFalse(NumberUtils.isNumber("0x"));
        assertFalse(NumberUtils.isNumber("1E+"));
        assertFalse(NumberUtils.isNumber("1E-"));
        assertFalse(NumberUtils.isNumber("--123"));
        assertFalse(NumberUtils.isNumber("++123"));
        assertFalse(NumberUtils.isNumber("abc"));
        assertFalse(NumberUtils.isNumber("123a"));
        assertFalse(NumberUtils.isNumber("12.3.4"));
        assertFalse(NumberUtils.isNumber("123L."));
        assertFalse(NumberUtils.isNumber("123.L"));
        assertFalse(NumberUtils.isNumber("0xAF."));
        assertFalse(NumberUtils.isNumber("0xAFf")); // Hexadecimal with type qualifier
        assertFalse(NumberUtils.isNumber("0xAFE")); // Hexadecimal with exponent
        assertFalse(NumberUtils.isNumber("e10")); // Exponent without preceding digit
        assertFalse(NumberUtils.isNumber("123.45L")); // Decimal with 'L' qualifier
        assertFalse(NumberUtils.isNumber("1e10.")); // Exponent followed by decimal point
        assertFalse(NumberUtils.isNumber("1.2e")); // Incomplete scientific notation
        assertFalse(NumberUtils.isNumber("1.2e+")); // Incomplete scientific notation
        assertFalse(NumberUtils.isNumber("1.2e-")); // Incomplete scientific notation
        assertFalse(NumberUtils.isNumber("0xG")); // Invalid hex digit
        assertFalse(NumberUtils.isNumber("123fL")); // Multiple type qualifiers
        assertFalse(NumberUtils.isNumber("123.e10")); // Missing digit after decimal for scientific
        assertFalse(NumberUtils.isNumber("123E")); // Incomplete scientific notation
        assertFalse(NumberUtils.isNumber("123.L")); // L qualifier with decimal
        assertFalse(NumberUtils.isNumber("123e10L")); // L qualifier with exponent
        assertFalse(NumberUtils.isNumber("0xAF L")); // Space before qualifier
        assertFalse(NumberUtils.isNumber("123 456")); // Spaces in between
        assertFalse(NumberUtils.isNumber("123-")); // Trailing hyphen
        assertFalse(NumberUtils.isNumber("123+")); // Trailing plus
    }

    @Test
    public void testIsNumber_EdgeCases() {
        assertTrue(NumberUtils.isNumber("0.0f"));
        assertTrue(NumberUtils.isNumber("-0"));
        assertTrue(NumberUtils.isNumber("+0"));
        assertTrue(NumberUtils.isNumber("0x1"));
        assertTrue(NumberUtils.isNumber("1E1"));
        assertTrue(NumberUtils.isNumber("1.0E1"));
        assertTrue(NumberUtils.isNumber("1.0e+1"));
        assertTrue(NumberUtils.isNumber("1.0e-1"));
        assertFalse(NumberUtils.isNumber("0x"));
        assertFalse(NumberUtils.isNumber("0xZ"));
        assertFalse(NumberUtils.isNumber("0x."));
        assertFalse(NumberUtils.isNumber("0x1."));
