        assertFalse(NumberUtils.isNumber("1.f"));
        assertFalse(NumberUtils.isNumber("1.d"));
        assertFalse(NumberUtils.isNumber("1e."));
        assertFalse(NumberUtils.isNumber("1e+"));
        assertFalse(NumberUtils.isNumber("1e-"));
        assertFalse(NumberUtils.isNumber("1eL"));
        assertFalse(NumberUtils.isNumber("1eF"));
        assertFalse(NumberUtils.isNumber("1eD"));
        assertFalse(NumberUtils.isNumber("1.e"));
        assertFalse(NumberUtils.isNumber("1.e+"));
        assertFalse(NumberUtils.isNumber("1.e-"));
        assertFalse(NumberUtils.isNumber("1.eL"));
        assertFalse(NumberUtils.isNumber("1.eF"));
        assertFalse(NumberUtils.isNumber("1.eD"));
    }

    @Test
    public void testIsNumber_LongMinMax() {
        assertTrue(NumberUtils.isNumber(String.valueOf(Long.MAX_VALUE)));
        assertTrue(NumberUtils.isNumber(String.valueOf(Long.MIN_VALUE)));
        assertTrue(NumberUtils.isNumber(String.valueOf(Long.MAX_VALUE) + "L"));
        assertTrue(NumberUtils.isNumber(String.valueOf(Long.MIN_VALUE) + "L"));
        assertFalse(NumberUtils.isNumber(String.valueOf(Long.MAX_VALUE) + ".0")); // Long max value with decimal
    }

    @Test
    public void testIsNumber_DoubleMinMax() {
        assertTrue(NumberUtils.isNumber(String.valueOf(Double.MAX_VALUE)));
        assertTrue(NumberUtils.isNumber(String.valueOf(Double.MIN_VALUE)));
        assertTrue(NumberUtils.isNumber(String.valueOf(Double.MAX_VALUE) + "D"));
        assertTrue(NumberUtils.isNumber(String.valueOf(Double.MIN_VALUE) + "D"));
        assertTrue(NumberUtils.isNumber(String.valueOf(Double.MAX_VALUE) + "f")); // Can be parsed as float
        assertTrue(NumberUtils.isNumber(String.valueOf(Double.MIN_VALUE) + "f")); // Can be parsed as float
    }

    @Test
    public void testIsNumber_FloatMinMax() {
        assertTrue(NumberUtils.isNumber(String.valueOf(Float.MAX_VALUE)));
        assertTrue(NumberUtils.isNumber(String.valueOf(Float.MIN_VALUE)));
        assertTrue(NumberUtils.isNumber(String.valueOf(Float.MAX_VALUE) + "F"));
        assertTrue(NumberUtils.isNumber(String.valueOf(Float.MIN_VALUE) + "F"));
    }

    @Test
    public void testIsNumber_LargeNumbers() {
        // Test with numbers that might exceed standard integer types but are still valid
        assertTrue(NumberUtils.isNumber("12345678901234567890L"));
        assertTrue(NumberUtils.isNumber("1.2345678901234567890E+100"));
        assertTrue(NumberUtils.isNumber("-1.2345678901234567890E-100"));
    }

    @Test
    public void testIsNumber_HexadecimalWithMixedCase() {
        assertTrue(NumberUtils.isNumber("0xAaBbCcDdEeFf"));
        assertTrue(NumberUtils.isNumber("0x1234567890abcdef"));
        assertTrue(NumberUtils.isNumber("0XFEDCBA9876543210"));
    }
