import org.apache.commons.lang.StringUtils;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtilsContainsIgnoreCaseTest {

    @Test
    public void testContainsIgnoreCase() {
        // R3: A null String or null search String will return false.
        assertFalse(StringUtils.containsIgnoreCase(null, "abc"));
        assertFalse(StringUtils.containsIgnoreCase("abc", null));
        assertFalse(StringUtils.containsIgnoreCase(null, null));

        // R3: An empty search String ("") is considered to be contained within any non-null String, including an empty String.
        assertTrue(StringUtils.containsIgnoreCase("", "")); // from Javadoc
        assertTrue(StringUtils.containsIgnoreCase("abc", "")); // from Javadoc
        assertTrue(StringUtils.containsIgnoreCase("ABC", ""));
        assertTrue(StringUtils.containsIgnoreCase("aBc", ""));

        // R2: agreement between contains and containsIgnoreCase when case does not matter
        String str1 = "hello world";
        String search1 = "world";
        assertEquals(StringUtils.contains(str1, search1), StringUtils.containsIgnoreCase(str1, search1));

        String str2 = "JAVA";
        String search2 = "java";
        assertTrue(StringUtils.containsIgnoreCase(str2, search2));
        assertFalse(StringUtils.contains(str2, search2)); // Case-sensitive should be false

        // R4: predictable change under a transformed input (changing case)
        String originalStr = "HelloWorld";
        String searchLower = "world";
        String searchUpper = "WORLD";
        String searchMixed = "WoRlD";
        assertTrue(StringUtils.containsIgnoreCase(originalStr, searchLower));
        assertTrue(StringUtils.containsIgnoreCase(originalStr, searchUpper));
        assertTrue(StringUtils.containsIgnoreCase(originalStr, searchMixed));
        assertTrue(StringUtils.containsIgnoreCase(originalStr.toLowerCase(), searchLower));
        assertTrue(StringUtils.containsIgnoreCase(originalStr.toUpperCase(), searchUpper));
        assertTrue(StringUtils.containsIgnoreCase(originalStr.toLowerCase(), searchUpper));
        assertTrue(StringUtils.containsIgnoreCase(originalStr.toUpperCase(), searchLower));

        // R3: Basic containment, ignoring case
        assertTrue(StringUtils.containsIgnoreCase("abc", "a")); // from Javadoc
        assertTrue(StringUtils.containsIgnoreCase("abc", "A")); // from Javadoc
        assertFalse(StringUtils.containsIgnoreCase("abc", "z")); // from Javadoc
        assertFalse(StringUtils.containsIgnoreCase("abc", "Z")); // from Javadoc
        assertTrue(StringUtils.containsIgnoreCase("Abc", "b"));
        assertTrue(StringUtils.containsIgnoreCase("aBc", "C"));
        assertTrue(StringUtils.containsIgnoreCase("ABC", "abc"));
        assertTrue(StringUtils.containsIgnoreCase("aBcDeF", "bCd"));
        assertTrue(StringUtils.containsIgnoreCase("aBcDeF", "BCd"));
        assertTrue(StringUtils.containsIgnoreCase("aBcDeF", "bcD"));

        // R3: No containment
        assertFalse(StringUtils.containsIgnoreCase("abc", "d"));
        assertFalse(StringUtils.containsIgnoreCase("abc", "ax"));
        assertFalse(StringUtils.containsIgnoreCase("abc", "abCde"));

        // R4: Search string longer than the main string
        assertFalse(StringUtils.containsIgnoreCase("a", "abc"));
        assertFalse(StringUtils.containsIgnoreCase("abc", "abcdef"));

        // R4: String with special characters
        assertTrue(StringUtils.containsIgnoreCase("!@#$", "@#"));
        assertTrue(StringUtils.containsIgnoreCase("!@#$", "!@#$"));
        assertFalse(StringUtils.containsIgnoreCase("!@#$", "%"));

        // R4: Empty string as the main string
        assertFalse(StringUtils.containsIgnoreCase("", "a"));
        assertFalse(StringUtils.containsIgnoreCase("", "ABC"));

        // R4: Single character strings
        assertTrue(StringUtils.containsIgnoreCase("a", "a"));
        assertTrue(StringUtils.containsIgnoreCase("A", "a"));
        assertTrue(StringUtils.containsIgnoreCase("a", "A"));
        assertFalse(StringUtils.containsIgnoreCase("a", "b"));

        // R4: Multiple occurrences, still true if any match
        assertTrue(StringUtils.containsIgnoreCase("ababab", "BAB"));
        assertTrue(StringUtils.containsIgnoreCase("ababab", "aB"));

        // R4: Locale-independent check (though not directly testable without specific locale-sensitive characters)
        // The docstring states it uses Locale.ROOT, implying consistent behavior.
        // We can test with characters that might have different uppercase representations in other locales,
        // but for English alphabet, it's straightforward.
        assertTrue(StringUtils.containsIgnoreCase("straße", "STRASSE")); // Example for German ß -> SS
        assertTrue(StringUtils.containsIgnoreCase("STRASSE", "straße"));
        assertTrue(StringUtils.containsIgnoreCase("Straße", "strasse"));
        assertTrue(StringUtils.containsIgnoreCase("strasse", "Straße"));
    }
}
