import org.apache.commons.lang.ClassUtils;
import org.junit.Test;
import static org.junit.Assert.*;

public class ClassUtilsGetShortClassNameTest {

    @Test
    public void testGetShortClassName_NullAndEmpty() {
        // R3: If the input class name is null or an empty string, an empty string is returned.
        assertEquals("", ClassUtils.getShortClassName(null));
        assertEquals("", ClassUtils.getShortClassName(""));
    }

    @Test
    public void testGetShortClassName_SimpleClassNames() {
        // R2: Agreement with getShortClassName(Class<?>)
        assertEquals(ClassUtils.getShortClassName(String.class), ClassUtils.getShortClassName("java.lang.String"));
        assertEquals(ClassUtils.getShortClassName(Integer.class), ClassUtils.getShortClassName("java.lang.Integer"));
        assertEquals(ClassUtils.getShortClassName(Object.class), ClassUtils.getShortClassName("java.lang.Object"));

        // R4: Predictable change - no package
        assertEquals("MyClass", ClassUtils.getShortClassName("MyClass"));
        assertEquals("AnotherClass", ClassUtils.getShortClassName("AnotherClass"));
    }

    @Test
    public void testGetShortClassName_InnerClasses() {
        // R3: For inner classes, it replaces the '$' separator with a '.' to maintain readability
        assertEquals("Map.Entry", ClassUtils.getShortClassName("java.util.Map$Entry")); // from Javadoc
        assertEquals("Outer.Inner", ClassUtils.getShortClassName("com.example.Outer$Inner"));
        assertEquals("Outer.Inner.Deep", ClassUtils.getShortClassName("com.example.Outer$Inner$Deep"));
        assertEquals("Outer.Inner", ClassUtils.getShortClassName("Outer$Inner")); // No package
    }

    @Test
    public void testGetShortClassName_ArrayTypes() {
        // R3: It correctly processes array type names by stripping the array encoding
        assertEquals("Object[]", ClassUtils.getShortClassName("[Ljava.lang.Object;")); // from Javadoc
        assertEquals("int[][]", ClassUtils.getShortClassName("[[I")); // from Javadoc
        assertEquals("String[]", ClassUtils.getShortClassName("[Ljava.lang.String;"));
        assertEquals("boolean[]", ClassUtils.getShortClassName("[Z"));
        assertEquals("byte[]", ClassUtils.getShortClassName("[B"));
        assertEquals("char[]", ClassUtils.getShortClassName("[C"));
        assertEquals("double[]", ClassUtils.getShortClassName("[D"));
        assertEquals("float[]", ClassUtils.getShortClassName("[F"));
        assertEquals("long[]", ClassUtils.getShortClassName("[J"));
        assertEquals("short[]", ClassUtils.getShortClassName("[S"));
        assertEquals("int[]", ClassUtils.getShortClassName("[I"));

        // R4: Predictable change - multiple dimensions
        assertEquals("Object[][][]", ClassUtils.getShortClassName("[[[Ljava.lang.Object;"));
        assertEquals("int[][][][]", ClassUtils.getShortClassName("[[[[I"));

        // R4: Predictable change - array of inner class
        assertEquals("Map.Entry[]", ClassUtils.getShortClassName("[Ljava.util.Map$Entry;"));
    }

    @Test
    public void testGetShortClassName_MixedCases() {
        // R4: Combination of inner class and array
        assertEquals("Outer.Inner[]", ClassUtils.getShortClassName("[Lcom.example.Outer$Inner;"));
        assertEquals("Outer.Inner[][]", ClassUtils.getShortClassName("[[Lcom.example.Outer$Inner;"));

        // R4: Class name with package but no inner class or array
        assertEquals("String", ClassUtils.getShortClassName("java.lang.String"));
        assertEquals("List", ClassUtils.getShortClassName("java.util.List"));
    }

    @Test
    public void testGetShortClassName_EdgeCases() {
        // R4: Class name starting with package separator
        assertEquals("Class", ClassUtils.getShortClassName(".Class"));
        assertEquals("Class", ClassUtils.getShortClassName("..Class"));

        // R4: Class name with multiple package separators
        assertEquals("Class", ClassUtils.getShortClassName("a.b.c.Class"));

        // R4: Class name with multiple inner class separators
        assertEquals("A.B.C", ClassUtils.getShortClassName("A$B$C"));

        // R4: Class name with only package separators
        assertEquals("", ClassUtils.getShortClassName("..."));

        // R4: Class name with only inner class separators
        assertEquals("", ClassUtils.getShortClassName("$$$"));

        // R4: Class name with mixed separators at the end
        assertEquals("Class.", ClassUtils.getShortClassName("package.Class."));
        assertEquals("Class$", ClassUtils.getShortClassName("package.Class$"));
    }

    @Test
    public void testGetShortClassName_WithShortCanonicalName() {
        // R2: Agreement with getShortCanonicalName after canonicalization
        assertEquals(ClassUtils.getShortCanonicalName("java.lang.String"), ClassUtils.getShortClassName("java.lang.String"));
        assertEquals(ClassUtils.getShortCanonicalName("java.util.Map$Entry"), ClassUtils.getShortClassName("java.util.Map$Entry"));
        assertEquals(ClassUtils.getShortCanonicalName("[Ljava.lang.Object;"), ClassUtils.getShortClassName("[Ljava.lang.Object;"));
        assertEquals(ClassUtils.getShortCanonicalName("[[I"), ClassUtils.getShortClassName("[[I"));
    }
}
