        stopWatch.start();
        Thread.sleep(100); // Simulate some time passing
        long startTime = stopWatch.getTime(); // Should be non-zero
        stopWatch.stop();
        long stopTime = stopWatch.getTime(); // Should be approximately startTime
        assertTrue(stopTime >= 0);
        assertTrue(stopTime >= startTime); // The time should be recorded
        assertEquals(StopWatch.STATE_STOPPED, getRunningState(stopWatch));
        assertEquals(StopWatch.STATE_UNSPLIT, getSplitState(stopWatch)); // Split state should be invalidated
    }

