        Thread.sleep(50);
        stopWatch.suspend();
        Thread.sleep(50); // Time should not be counted here
        long timeBeforeStop = stopWatch.getTime();
        stopWatch.stop();
        long timeAfterStop = stopWatch.getTime();
        assertTrue(timeAfterStop >= 0);
        assertTrue(timeAfterStop >= timeBeforeStop); // Time should be recorded up to suspension
        assertEquals(StopWatch.STATE_STOPPED, getRunningState(stopWatch));
        assertEquals(StopWatch.STATE_UNSPLIT, getSplitState(stopWatch)); // Split state should be invalidated
