import org.apache.commons.lang.math.NumberUtils;
import org.junit.Test;
import java.math.BigDecimal;
import java.math.BigInteger;

import static org.junit.Assert.*;

public class NumberUtilsCreateNumberTest {

    @Test
    public void testCreateNumberNull() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberEmptyString() {
        NumberUtils.createNumber("");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberBlankString() {
        NumberUtils.createNumber("   ");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberInvalidFormat() {
        NumberUtils.createNumber("abc");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberDoubleDash() {
        NumberUtils.createNumber("--123");
    }

    @Test
    public void testCreateNumberInteger() {
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
        assertEquals(Integer.valueOf(-45), NumberUtils.createNumber("-45"));
        assertEquals(Integer.valueOf(0), NumberUtils.createNumber("0"));
        assertEquals(Integer.valueOf(Integer.MAX_VALUE), NumberUtils.createNumber(String.valueOf(Integer.MAX_VALUE)));
        assertEquals(Integer.valueOf(Integer.MIN_VALUE), NumberUtils.createNumber(String.valueOf(Integer.MIN_VALUE)));
    }

    @Test
    public void testCreateNumberLong() {
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123L"));
        assertEquals(Long.valueOf(-45L), NumberUtils.createNumber("-45l"));
        assertEquals(Long.valueOf(Integer.MAX_VALUE + 1L), NumberUtils.createNumber(String.valueOf(Integer.MAX_VALUE + 1L)));
        assertEquals(Long.valueOf(Long.MAX_VALUE), NumberUtils.createNumber(String.valueOf(Long.MAX_VALUE)));
        assertEquals(Long.valueOf(Long.MIN_VALUE), NumberUtils.createNumber(String.valueOf(Long.MIN_VALUE)));
    }

    @Test
    public void testCreateNumberFloat() {
        assertEquals(Float.valueOf(1.23f), NumberUtils.createNumber("1.23f"));
        assertEquals(Float.valueOf(-4.5e-2f), NumberUtils.createNumber("-4.5e-2F"));
        assertEquals(Float.valueOf(0.0f), NumberUtils.createNumber("0.0f"));
        assertEquals(Float.valueOf(Float.MAX_VALUE), NumberUtils.createNumber(String.valueOf(Float.MAX_VALUE) + "f"));
        assertEquals(Float.valueOf(Float.MIN_VALUE), NumberUtils.createNumber(String.valueOf(Float.MIN_VALUE) + "f"));
    }

    @Test
    public void testCreateNumberDouble() {
        assertEquals(Double.valueOf(1.23d), NumberUtils.createNumber("1.23d"));
        assertEquals(Double.valueOf(-4.5e-2d), NumberUtils.createNumber("-4.5e-2D"));
        assertEquals(Double.valueOf(0.0d), NumberUtils.createNumber("0.0d"));
        assertEquals(Double.valueOf(Double.MAX_VALUE), NumberUtils.createNumber(String.valueOf(Double.MAX_VALUE) + "d"));
        assertEquals(Double.valueOf(Double.MIN_VALUE), NumberUtils.createNumber(String.valueOf(Double.MIN_VALUE) + "d"));
    }

    @Test
    public void testCreateNumberHexadecimal() {
        assertEquals(Integer.valueOf(0xAF), NumberUtils.createNumber("0xAF"));
        assertEquals(Integer.valueOf(-0x10), NumberUtils.createNumber("-0x10"));
        assertEquals(Long.valueOf(0xFFFFFFFFFFFL), NumberUtils.createNumber("0xFFFFFFFFFFFL"));
    }

    @Test
    public void testCreateNumberNoSuffixIntegerLike() {
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
        assertEquals(Long.valueOf(Integer.MAX_VALUE + 1L), NumberUtils.createNumber(String.valueOf(Integer.MAX_VALUE + 1L)));
        assertEquals(new BigInteger("9223372036854775808"), NumberUtils.createNumber("9223372036854775808")); // Long.MAX_VALUE + 1
    }

    @Test
    public void testCreateNumberNoSuffixFloatingPointLike() {
        assertEquals(Float.valueOf(1.23f), NumberUtils.createNumber("1.23"));
        assertEquals(Double.valueOf(1.2345678901234567d), NumberUtils.createNumber("1.2345678901234567")); // Exceeds float precision
        assertEquals(new BigDecimal("1.23456789012345678901234567890123456789"), NumberUtils.createNumber("1.23456789012345678901234567890123456789")); // Exceeds double precision
        assertEquals(Double.valueOf(1.0e20), NumberUtils.createNumber("1.0e20"));
    }

    @Test
    public void testCreateNumberPrecisionFloatToDouble() {
        // A number that can be represented by Double but not accurately by Float
        String preciseDoubleString = "1.2345678901234567";
        Number result = NumberUtils.createNumber(preciseDoubleString);
        assertTrue(result instanceof Double);
        assertEquals(Double.valueOf(preciseDoubleString), result);
    }

    @Test
    public void testCreateNumberPrecisionDoubleToBigDecimal() {
        // A number that can be represented by BigDecimal but not accurately by Double
        String preciseBigDecimalString = "1.23456789012345678901234567890123456789";
        Number result = NumberUtils.createNumber(preciseBigDecimalString);
        assertTrue(result instanceof BigDecimal);
        assertEquals(new BigDecimal(preciseBigDecimalString), result);
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberInvalidFloatSuffix() {
        NumberUtils.createNumber("1.23x");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberInvalidLongSuffix() {
        NumberUtils.createNumber("123y");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberInvalidDoubleSuffix() {
        NumberUtils.createNumber("1.23z");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberFloatOverflow() {
        NumberUtils.createNumber(String.valueOf(Double.MAX_VALUE) + "f"); // Too large for float
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberLongOverflow() {
        NumberUtils.createNumber(new BigInteger(String.valueOf(Long.MAX_VALUE)).add(BigInteger.ONE).toString() + "L"); // Too large for long
    }

    @Test
    public void testCreateNumberNegativeZero() {
        assertEquals(Float.valueOf(-0.0f), NumberUtils.createNumber("-0.0f"));
        assertEquals(Double.valueOf(-0.0d), NumberUtils.createNumber("-0.0d"));
        assertEquals(Integer.valueOf(0), NumberUtils.createNumber("-0"));
    }

    @Test
    public void testCreateNumberExponentOnly() {
        assertEquals(Double.valueOf(1.0e5), NumberUtils.createNumber("1e5"));
        assertEquals(Double.valueOf(1.0e-5), NumberUtils.createNumber("1e-5"));
        assertEquals(Float.valueOf(1.0e5f), NumberUtils.createNumber("1e5f"));
    }

    @Test
    public void testCreateNumberLeadingZeroes() {
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("0123"));
        assertEquals(Double.valueOf(0.123d), NumberUtils.createNumber("0.123"));
    }

    @Test
    public void testCreateNumberWithDecimalPointOnly() {
        assertEquals(Double.valueOf(0.0d), NumberUtils.createNumber(".0"));
        assertEquals(Double.valueOf(0.0d), NumberUtils.createNumber("0."));
        assertEquals(Double.valueOf(0.5d), NumberUtils.createNumber(".5"));
        assertEquals(Double.valueOf(5.0d), NumberUtils.createNumber("5."));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberInvalidHex() {
        NumberUtils.createNumber("0xG");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberInvalidHexWithSuffix() {
        NumberUtils.createNumber("0xFL"); // Hex with L suffix is valid
        NumberUtils.createNumber("0xFG"); // Invalid hex digit
    }

    @Test
    public void testCreateNumberBigInteger() {
        String bigIntStr = "123456789012345678901234567890";
        assertEquals(new BigInteger(bigIntStr), NumberUtils.createNumber(bigIntStr));
    }

    @Test
    public void testCreateNumberBigDecimal() {
        String bigDecimalStr = "12345678901234567890.12345678901234567890";
        assertEquals(new BigDecimal(bigDecimalStr), NumberUtils.createNumber(bigDecimalStr));
    }

    @Test
    public void testCreateNumberFloatInfinity() {
        // Float.POSITIVE_INFINITY is not directly parsable from string as "Infinityf" by createNumber
        // but large numbers should result in Double or BigDecimal
        String largeFloat = "3.4028235E38f"; // Max float value
        assertEquals(Float.valueOf(largeFloat), NumberUtils.createNumber(largeFloat));
    }

    @Test
    public void testCreateNumberDoubleInfinity() {
        // Double.POSITIVE_INFINITY is not directly parsable from string as "Infinityd" by createNumber
        // but large numbers should result in Double or BigDecimal
        String largeDouble = "1.7976931348623157E308d"; // Max double value
        assertEquals(Double.valueOf(largeDouble), NumberUtils.createNumber(largeDouble));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberInvalidCharacterInMiddle() {
        NumberUtils.createNumber("123a456");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberInvalidCharacterAfterSuffix() {
        NumberUtils.createNumber("123fA");
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumberInvalidCharacterBeforeSuffix() {
        NumberUtils.createNumber("123.f");
    }

    @Test
    public void testCreateNumberNegativeHex() {
        assertEquals(Integer.valueOf(-10), NumberUtils.createNumber("-0xA"));
        assertEquals(Long.valueOf(-255L), NumberUtils.createNumber("-0xFFL"));
    }

    @Test
    public void testCreateNumberZeroHex() {
        assertEquals(Integer.valueOf(0), NumberUtils.createNumber("0x0"));
        assertEquals(Long.valueOf(0L), NumberUtils.createNumber("0x0L"));
    }

    @Test
    public void testCreateNumberWithSignOnly() {
        // These should throw NumberFormatException as they are not valid numbers
        try {
            NumberUtils.createNumber("+");
            fail("Expected NumberFormatException for '+'");
        } catch (NumberFormatException e) {
            // Expected
        }
        try {
            NumberUtils.createNumber("-");
            fail("Expected NumberFormatException for '-'");
        } catch (NumberFormatException e) {
            // Expected
        }
    }

    @Test
    public void testCreateNumberWithDecimalPointAndExponent() {
        assertEquals(Double.valueOf(1.23e4), NumberUtils.createNumber("1.23e4"));
        assertEquals(Float.valueOf(1.23e-4f), NumberUtils.createNumber("1.23e-4f"));
    }

    @Test
    public void testCreateNumberWithOnlyExponent() {
        // "e10" is not a valid number
        try {
            NumberUtils.createNumber("e10");
            fail("Expected NumberFormatException for 'e10'");
        } catch (NumberFormatException e) {
            // Expected
        }
    }

    @Test
    public void testCreateNumberWithOnlyDecimalPoint() {
        // "." is not a valid number
        try {
            NumberUtils.createNumber(".");
            fail("Expected NumberFormatException for '.'");
        } catch (NumberFormatException e) {
            // Expected
        }
    }
