import org.junit.Test;
import static org.junit.Assert.*;

public class StrBuilderAppendFixedWidthPadRightTest {

    @Test
    public void testAppendFixedWidthPadRight_StringShorterThanWidth() {
        StrBuilder sb = new StrBuilder();
        String obj = "hello";
        int width = 10;
        char padChar = '-';
        sb.appendFixedWidthPadRight(obj, width, padChar);
        assertEquals("hello-----", sb.toString());

        sb = new StrBuilder();
        obj = "a";
        width = 5;
        padChar = 'x';
        sb.appendFixedWidthPadRight(obj, width, padChar);
        assertEquals("axxxx", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_StringEqualToWidth() {
        StrBuilder sb = new StrBuilder();
        String obj = "abcdef";
        int width = 6;
        char padChar = ' ';
        sb.appendFixedWidthPadRight(obj, width, padChar);
        assertEquals("abcdef", sb.toString());

        sb = new StrBuilder();
        obj = "12345";
        width = 5;
        padChar = '0';
        sb.appendFixedWidthPadRight(obj, width, padChar);
        assertEquals("12345", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_StringLongerThanWidth() {
        StrBuilder sb = new StrBuilder();
        String obj = "longstring";
        int width = 5;
        char padChar = ' ';
        sb.appendFixedWidthPadRight(obj, width, padChar);
        assertEquals("longs", sb.toString());

        sb = new StrBuilder();
        obj = "verylongstring";
        width = 3;
        padChar = 'x';
        sb.appendFixedWidthPadRight(obj, width, padChar);
        assertEquals("ver", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_NullObject() {
        StrBuilder sb = new StrBuilder();
        sb.setNullText("NULL");
        Object obj = null;
        int width = 7;
        char padChar = '_';
        sb.appendFixedWidthPadRight(obj, width, padChar);
        assertEquals("NULL___", sb.toString());

        sb = new StrBuilder();
        sb.setNullText(""); // Empty null text
        obj = null;
        width = 5;
        padChar = '*';
        sb.appendFixedWidthPadRight(obj, width, padChar);
        assertEquals("*****", sb.toString());

        sb = new StrBuilder();
        sb.setNullText("N"); // Null text shorter than width
        obj = null;
        width = 3;
        padChar = 'p';
        sb.appendFixedWidthPadRight(obj, width, padChar);
        assertEquals("Npp", sb.toString());

        sb = new StrBuilder();
        sb.setNullText("NULLTEXT"); // Null text longer than width
        obj = null;
        width = 4;
        padChar = 'q';
        sb.appendFixedWidthPadRight(obj, width, padChar);
        assertEquals("NULL", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_ZeroWidth() {
        StrBuilder sb = new StrBuilder();
        String obj = "anything";
        int width = 0;
        char padChar = ' ';
        sb.appendFixedWidthPadRight(obj, width, padChar);
        assertEquals("", sb.toString());

        sb = new StrBuilder("initial");
        obj = "test";
        width = 0;
        padChar = 'x';
        sb.appendFixedWidthPadRight(obj, width, padChar);
        assertEquals("initial", sb.toString());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testAppendFixedWidthPadRight_NegativeWidth() {
        StrBuilder sb = new StrBuilder();
        String obj = "test";
        int width = -5;
        char padChar = ' ';
        sb.appendFixedWidthPadRight(obj, width, padChar);
    }

    @Test
    public void testAppendFixedWidthPadRight_EmptyString() {
        StrBuilder sb = new StrBuilder();
        String obj = "";
        int width = 5;
        char padChar = 'z';
        sb.appendFixedWidthPadRight(obj, width, padChar);
        assertEquals("zzzzz", sb.toString());

        sb = new StrBuilder("prefix");
        obj = "";
        width = 3;
        padChar = 'y';
        sb.appendFixedWidthPadRight(obj, width, padChar);
        assertEquals("prefixyyy", sb.toString());
    }

    @Test
    public void testAppendFixedWidthPadRight_Chaining() {
        StrBuilder sb = new StrBuilder();
        sb.appendFixedWidthPadRight("one", 5, ' ')
                .appendFixedWidthPadRight("two", 5, '-')
                .appendFixedWidthPadRight("three", 2, 'x');
        assertEquals("one  two--th", sb.toString());
    }

