        char padChar = '0';
        sb1.appendFixedWidthPadRight(value, width, padChar);

        StrBuilder sb2 = new StrBuilder();
        String obj = String.valueOf(value);
        sb2.appendFixedWidthPadRight(obj, width, padChar);

