import org.apache.commons.lang.enums.ValuedEnum;
import org.junit.Test;
import static org.junit.Assert.*;

public class ValuedEnumCompareToTest {

    private static class TestValuedEnum extends ValuedEnum {
        protected TestValuedEnum(String name, int value) {
            super(name, value);
        }
    }

    @Test
    public void testCompareTo_EqualValues() {
        TestValuedEnum enum1 = new TestValuedEnum("ONE", 1);
        TestValuedEnum enum2 = new TestValuedEnum("ONE_COPY", 1);
        assertEquals(0, enum1.compareTo(enum2));
        assertEquals(0, enum2.compareTo(enum1));
    }

    @Test
    public void testCompareTo_LesserValue() {
        TestValuedEnum enum1 = new TestValuedEnum("ONE", 1);
        TestValuedEnum enum2 = new TestValuedEnum("TWO", 2);
        assertTrue(enum1.compareTo(enum2) < 0);
    }

    @Test
    public void testCompareTo_GreaterValue() {
        TestValuedEnum enum1 = new TestValuedEnum("TWO", 2);
        TestValuedEnum enum2 = new TestValuedEnum("ONE", 1);
        assertTrue(enum1.compareTo(enum2) > 0);
    }

    @Test
    public void testCompareTo_SelfComparison() {
        TestValuedEnum enum1 = new TestValuedEnum("ANY", 10);
        assertEquals(0, enum1.compareTo(enum1));
    }

    @Test(expected = NullPointerException.class)
    public void testCompareTo_NullOther() {
        TestValuedEnum enum1 = new TestValuedEnum("TEST", 5);
        enum1.compareTo(null);
    }

    @Test(expected = ClassCastException.class)
    public void testCompareTo_DifferentClassType() {
        TestValuedEnum enum1 = new TestValuedEnum("TEST", 5);
        Object other = new Object();
        enum1.compareTo(other);
    }

    @Test
    public void testCompareTo_NegativeValues() {
        TestValuedEnum enum1 = new TestValuedEnum("NEG_FIVE", -5);
        TestValuedEnum enum2 = new TestValuedEnum("NEG_TEN", -10);
        assertTrue(enum1.compareTo(enum2) > 0);
        assertTrue(enum2.compareTo(enum1) < 0);
    }

    @Test
